// Helper Functions for Turf Control
function getHeatColor(heat) {
  if (heat < 20) return '#8a9a6a';
  if (heat < 50) return '#c0a040';
  return '#8b3a3a';
}

function getRiskColor(riskLevel) {
  switch(riskLevel) {
    case 'low': return '#8a9a6a';
    case 'medium': return '#c0a040';
    case 'high': return '#8b3a3a';
    case 'very high': return '#8b3a3a';
    case 'extreme': return '#8b6a4a';
    default: return '#d4c4a0';
  }
}

// Turf Control Action Functions
async function renewCorruption(officialId) {
  const official = player.corruptedOfficials.find(o => o.id === officialId);
  if (!official) {
    showBriefNotification('Official not found!', 'danger');
    return;
  }

  const target = corruptionTargets.find(t => t.id === official.targetId);
  if (!target) {
    showBriefNotification('Corruption target data missing!', 'danger');
    return;
  }

  const renewalCost = Math.floor(target.baseCost * 0.6); // 60% of original cost to renew

  if (player.money < renewalCost) {
    showBriefNotification(`Need $${renewalCost.toLocaleString()} to renew the ${target.name} bribe!`, 'danger');
    return;
  }

  if (await ui.confirm(`Renew ${target.name} bribe for $${renewalCost.toLocaleString()}?\n\nThis extends their loyalty by ${target.benefits.duration} more days.`)) {
    player.money -= renewalCost;
    official.expirationDate = Math.max(official.expirationDate, Date.now()) + (target.benefits.duration * 24 * 60 * 60 * 1000);

    // Small risk on renewal too
    if (Math.random() < 0.08) {
      player.heat += Math.floor(Math.random() * 10) + 5;
      showBriefNotification('Bribe renewed, but someone may have noticed the exchange...', 'warning');
      logAction(`${target.name}'s loyalty renewed, but whispers travel fast in the shadows.`);
    } else {
      showBriefNotification(`${target.name}'s corruption renewed for ${target.benefits.duration} days!`, 'success');
      logAction(`${target.name} remains loyal -- for the right price. The machine keeps turning.`);
    }

    updateUI();
    showCorruption();
  }
}

async function corruptOfficial(targetId) {
  const target = corruptionTargets.find(t => t.id === targetId);
  if (!target) return;

  if (player.money < target.baseCost) {
    showBriefNotification(`Need $${target.baseCost.toLocaleString()} to bribe the ${target.name}!`, 'danger');
    return;
  }

  if (await ui.confirm(`Bribe ${target.name} for $${target.baseCost.toLocaleString()}? Duration: ${target.benefits.duration} days`)) {
    player.money -= target.baseCost;

    const corruption = {
      id: `corruption_${Date.now()}`,
      targetId: target.id,
      startDate: Date.now(),
      expirationDate: Date.now() + (target.benefits.duration * 24 * 60 * 60 * 1000),
      benefits: target.benefits
    };

    player.corruptedOfficials.push(corruption);

    // Corrupting officials reduces heat
    player.heat = Math.max(0, (player.heat || 0) - 5);
    if (player.streetReputation) {
      player.streetReputation.underground = Math.min(100, (player.streetReputation.underground || 0) + 2);
    }

    // Risk of getting caught
    if (Math.random() < (target.riskLevel === 'extreme' ? 0.3 : target.riskLevel === 'high' ? 0.2 : 0.1)) {
      player.heat += Math.floor(Math.random() * 20) + 10;
      showBriefNotification('Bribe successful, but someone may have noticed...', 'warning');
      logAction(`${target.name} has been corrupted, but you sense eyes watching your every move. The price of power is constant vigilance.`);
    } else {
      showBriefNotification(`${target.name} corrupted successfully!`, 'success');
      logAction(`${target.name} is now in your pocket. Money talks, and corruption walks. Your influence grows in the shadows.`);
    }

    updateUI();
    showCorruption();
  }
}

// Cache of available businesses so approachBusiness can look them up after render
let _cachedAvailableBusinesses = [];

function approachBusiness(businessId, territoryId) {
  // Look up from the cached generated businesses (set during showProtectionRackets)
  const business = _cachedAvailableBusinesses.find(b => b.id === businessId);
  if (!business) return;

  // Success chance based on gang reputation and turf power
  let successChance = 0.4 + (player.turfReputation / 100) + (player.turfPower / 1000);
  // Civilians streetRep: positive = locals cooperate, negative = locals resist
  const civRepMod = getStreetRepBonus('civilians', 0.05, 0.10, 0.15, 0.25);
  successChance += civRepMod;
  successChance = Math.min(0.9, Math.max(0.1, successChance));

  if (Math.random() < successChance) {
    const racket = {
      id: `racket_${Date.now()}`,
      businessId: business.templateId, // Store original template ID for later lookups
      territoryId: territoryId,
      businessIndex: business.businessIndex,
      weeklyPayment: business.basePayment,
      fearLevel: 5.0,
      lastCollection: Date.now()
    };

    player.protectionRackets.push(racket);
    player.turfReputation += 5;

    // Protection rackets hurt civilian relations (intimidation)
    if (player.streetReputation) {
      player.streetReputation.civilians = Math.max(-100, (player.streetReputation.civilians || 0) - 2);
    }

    showBriefNotification(`${business.name} pays $${business.basePayment.toLocaleString()} every 24h for protection`, 'success');
    logAction(`${business.name} now pays tribute. Fear is the foundation of respect, and respect is the currency of power.`);
  } else {
    // Failed approach - business calls police or refuses
    if (Math.random() < 0.3) {
      player.heat += Math.floor(Math.random() * 15) + 5;
      showBriefNotification(`${business.name} called the police! Heat up.`, 'danger');
      logAction(`${business.name} refused your offer and called the authorities. Sometimes the sheep bite back.`);
    } else {
      showBriefNotification(`${business.name} refused your offer.`, 'warning');
      logAction(`${business.name} shows no fear. Some prey require a different approach.`);
    }
  }

  updateUI();
  showProtectionRackets();
}

function collectProtection(racketId) {
  const racket = player.protectionRackets.find(r => r.id === racketId);
  if (!racket) return;

  const business = protectionBusinesses.find(b => b.id === racket.businessId);
  const timeSinceLastCollection = Date.now() - racket.lastCollection;
  const hoursElapsed = Math.floor(timeSinceLastCollection / (60 * 60 * 1000));

  if (hoursElapsed < 24) {
    const hrsLeft = 24 - hoursElapsed;
    showBriefNotification(`Come back in ${hrsLeft}h. Give them time to make money first.`, 'warning');
    return;
  }

  const periodsElapsed = Math.floor(hoursElapsed / 24);
  let totalPayment = racket.weeklyPayment * periodsElapsed;
  // Civilians streetRep: positive = locals pay more willingly, negative = less
  const civPayMod = getStreetRepBonus('civilians', 0.05, 0.10, 0.20, 0.30);
  if (civPayMod !== 0) totalPayment = Math.max(1, Math.floor(totalPayment * (1 + civPayMod)));
  player.money += totalPayment;
  racket.lastCollection = Date.now();

  // Collecting protection money slightly hurts civilian reputation
  if (player.streetReputation) {
    player.streetReputation.civilians = Math.max(-100, (player.streetReputation.civilians || 0) - 1);
  }

  // Maintain fear level
  racket.fearLevel = Math.min(10, racket.fearLevel + 0.5);

  showBriefNotification(`Collected $${totalPayment.toLocaleString()} from ${business.name}`, 'success');
  logAction(`${business.name} pays their tribute without question. Fear keeps the money flowing like clockwork.`);

  updateUI();
  showProtectionRackets();
}

function pressureBusiness(racketId) {
  const racket = player.protectionRackets.find(r => r.id === racketId);
  if (!racket) return;

  const business = protectionBusinesses.find(b => b.id === racket.businessId);

  if (Math.random() < 0.7) {
    // Successful pressure - increase payment
    const increase = Math.floor(business.basePayment * 0.2);
    racket.weeklyPayment = Math.min(business.maxExtortion, racket.weeklyPayment + increase);
    racket.fearLevel = Math.min(10, racket.fearLevel + 1);

    showBriefNotification(`${business.name} agrees to pay more! Payment increased by $${increase.toLocaleString()}.`, 'success');
    logAction(`Applied pressure to ${business.name}. A reminder of consequences speaks louder than words.`);
  } else {
    // Pressure backfires
    if (Math.random() < 0.4) {
      // Business calls police
      player.heat += Math.floor(Math.random() * 20) + 10;
      showBriefNotification(`Your pressure tactics backfired! ${business.name} called the police.`, 'danger');
      logAction(`${business.name} cracked under pressure and called the cops. Sometimes intimidation cuts both ways.`);
    } else {
      // Business closes down
      player.protectionRackets = player.protectionRackets.filter(r => r.id !== racketId);
      showBriefNotification(`You pushed too hard! ${business.name} closed down and left the area.`, 'danger');
      logAction(`${business.name} shuttered their doors permanently. You killed the golden goose.`);
    }
  }

  updateUI();
  showProtectionRackets();
}

async function dropProtection(racketId) {
  if (await ui.confirm('Are you sure you want to drop this protection racket?')) {
    player.protectionRackets = player.protectionRackets.filter(r => r.id !== racketId);
    showBriefNotification('Protection racket dropped.', 'warning');
    logAction('Released a business from your protection. Sometimes mercy has its own rewards.');

    showProtectionRackets();
  }
}

// -- Corruption Benefit Helper ---
// Returns the best (highest) value for a given corruption benefit type
// among all currently active (non-expired) corrupted officials.
function getCorruptionBenefit(benefitType) {
  const officials = player.corruptedOfficials || [];
  const now = Date.now();
  let best = 0;
  officials.forEach(o => {
    if (o.expirationDate > now && o.benefits && o.benefits[benefitType]) {
      best = Math.max(best, o.benefits[benefitType]);
    }
  });
  return best;
}

// -- Faction Effects Helper ---
// Returns the highest-tier effect description for the given faction based on
// the player's current streetReputation. Returns null if no threshold is met.
function getActiveFactionEffect(factionKey) {
  const effects = factionEffects[factionKey];
  if (!effects) return null;
  const rep = (player.streetReputation && player.streetReputation[factionKey]) || 0;
  if (rep >= 0) {
    // Scan positive effects from highest threshold down
    for (let i = effects.positiveEffects.length - 1; i >= 0; i--) {
      if (rep >= effects.positiveEffects[i].level) return { tier: effects.positiveEffects[i].level, effect: effects.positiveEffects[i].effect, positive: true };
    }
  } else {
    // Scan negative effects from lowest (most negative) threshold up
    for (let i = effects.negativeEffects.length - 1; i >= 0; i--) {
      if (rep <= effects.negativeEffects[i].level) return { tier: effects.negativeEffects[i].level, effect: effects.negativeEffects[i].effect, positive: false };
    }
  }
  return null;
}

// Returns a numeric multiplier/modifier based on a faction's streetReputation.
// tier25 = value at ±25, tier50 = value at ±50, tier75 = value at ±75, tier100 = value at ±100.
// Positive rep returns positive modifier, negative rep returns negative modifier.
function getStreetRepBonus(factionKey, tier25, tier50, tier75, tier100) {
  const rep = (player.streetReputation && player.streetReputation[factionKey]) || 0;
  const absRep = Math.abs(rep);
  const sign = rep >= 0 ? 1 : -1;
  if (absRep >= 100) return sign * tier100;
  if (absRep >= 75) return sign * tier75;
  if (absRep >= 50) return sign * tier50;
  if (absRep >= 25) return sign * tier25;
  return 0;
}

// -- Rival Respect Helper ---
// Updates respect toward the player for a specific rival (by ID).
// Also syncs to player.relationships for UI display.
function updateRivalRespect(rivalId, amount) {
  if (!player.relationships) player.relationships = {};
  player.relationships[rivalId] = Math.max(-100, Math.min(100,
    (player.relationships[rivalId] || 0) + amount));
  // Sync back to rivalKingpins array
  const rivals = player.rivalKingpins || RIVAL_KINGPINS;
  const rival = rivals.find(r => r.id === rivalId);
  if (rival) rival.respectTowardPlayer = player.relationships[rivalId];
}

// Updates respect toward the player for ALL rivals in a given faction.
function updateFactionRivalRespect(factionKey, amount) {
  const rivals = player.rivalKingpins || RIVAL_KINGPINS;
  rivals.filter(r => r.faction === factionKey).forEach(r => updateRivalRespect(r.id, amount));
}

// Process Turf Events and Income (called periodically) -- delegates to turf
function processTurfOpsWrapper() {
  processTurfOperations();

  // Generate random turf events (30% chance each cycle)
  if ((player.turf?.owned || []).length > 0 && Math.random() < 0.30) {
    generateTurfEvent();
  }

  // Expire corrupted officials (kept from original)
  const currentTime = Date.now();
  player.corruptedOfficials = (player.corruptedOfficials || []).filter(official => {
    if (official.expirationDate <= currentTime) {
      const target = (typeof corruptionTargets !== 'undefined') ? corruptionTargets.find(t => t.id === official.targetId) : null;
      logAction(`${target ? target.name : 'A corrupted official'} is no longer under your influence.`);
      return false;
    }
    return true;
  });
}

function generateTurfEvent() {
  // Generate events using the richer turfEvents array (probability-weighted)
  initTurfZones();
  const owned = player.turf.owned || [];
  if (owned.length === 0) return;

  // Weighted random selection based on probability
  const totalProb = turfEvents.reduce((sum, e) => sum + e.probability, 0);
  let roll = Math.random() * totalProb;
  let evt = turfEvents[0];
  for (const te of turfEvents) {
    roll -= te.probability;
    if (roll <= 0) { evt = te; break; }
  }

  const randomZoneId = owned[Math.floor(Math.random() * owned.length)];
  const zone = (player.turf._zones || []).find(z => z.id === randomZoneId);

  // Apply effects from the richer schema
  if (evt.effects.heatIncrease) {
    const heatGain = Math.round(evt.effects.heatIncrease * 50);
    player.heat = Math.min(100, (player.heat || 0) + heatGain);
  }
  if (evt.effects.incomeReduction) {
    // Temporarily reduce income from the zone for event duration (stored on event)
    player.dirtyMoney = Math.max(0, (player.dirtyMoney || 0) - Math.floor((player.turf.income || 0) * evt.effects.incomeReduction));
    logAction(`Income reduced by ${Math.floor(evt.effects.incomeReduction * 100)}% due to ${evt.name}.`);
  }
  if (evt.effects.incomeIncrease) {
    const bonus = Math.floor((player.turf.income || 500) * evt.effects.incomeIncrease);
    player.dirtyMoney = (player.dirtyMoney || 0) + bonus;
    logAction(`Bonus income: +$${bonus.toLocaleString()} from ${evt.name}.`);
  }
  if (evt.effects.recruitmentPenalty && player.gang) {
    // Reduce gang morale briefly -- lower max recruitable
    logAction(`Community resistance makes recruiting harder in ${zone?.name || 'your turf'}.`);
  }
  if (evt.effects.businessOpportunity) {
    player.turfReputation = (player.turfReputation || 0) + 5;
    logAction('New business opportunities give you +5 turf respect.');
  }
  if (evt.effects.conflictRisk && Math.random() < evt.effects.conflictRisk) {
    // Trigger a bonus rival family attack on this zone
    const rivals = getActiveRivals();
    const attackingFamily = rivals.length > 0 ? rivals[Math.floor(Math.random() * rivals.length)] : null;
    const attackStrength = 50 + Math.floor(Math.random() * 60);
    const attackerName = attackingFamily || 'Encroaching Gang';
    const attackerLabel = attackingFamily ? RIVAL_FAMILIES[attackingFamily]?.name || attackerName : attackerName;
    const result = processTurfAttack(zone, attackerName, attackStrength, player);
    if (result?.lostTurf) {
      if (attackingFamily) zone.controlledBy = attackingFamily;
      logAction(`<strong>${attackerLabel}</strong> seized <strong>${zone?.name || 'a zone'}</strong> during territorial unrest!`);
    } else {
      logAction(`You repelled <strong>${attackerLabel}</strong> at <strong>${zone?.name || 'a zone'}</strong>.`);
    }
  }

  // Merge turf.reputation into turfReputation
  player.turf.reputation = (player.turf.reputation || 0) + (evt.category === 'opportunity' ? 10 : 0);
  player.turfReputation = (player.turfReputation || 0) + (evt.category === 'opportunity' ? 10 : 0);

  player.turf.events = player.turf.events || [];
  player.turf.events.push({ id: evt.id, name: evt.name, description: evt.description, duration: evt.effects.duration || 3, zone: randomZoneId, category: evt.category });

  // Trim old events
  if (player.turf.events.length > 5) player.turf.events = player.turf.events.slice(-5);

  logAction(`Turf Event in <strong>${zone?.name || 'your turf'}</strong>: ${evt.name} -- ${evt.description}`);
}
function updateUI() {
  // Process economy sinks (hourly upkeep)
  if (typeof processEconomySinks === 'function') processEconomySinks();

  // Check new achievements
  if (typeof checkNewAchievements === 'function') checkNewAchievements();

  // Render notification badges
  if (typeof renderNotificationBadges === 'function') renderNotificationBadges();

  // Synchronize gang member counts to prevent drift
  if (player.gang && player.gang.gangMembers) {
    // Ensure legacy count matches actual array length
    player.gang.members = player.gang.gangMembers.length;
  }

  // Recalculate all power (equipment + gang + turf) every UI update
  recalculatePower();

  // Keep legacy turf count in sync with turf owned zones
  player.territory = (player.turf?.owned || []).length;

  // Update player portrait and name
  if (player.name) {
    const nameDisplay = document.getElementById('player-name-display');
    if (nameDisplay) {
      nameDisplay.textContent = player.title ? `${player.name} -- "${player.title}"` : player.name;
    }
  }

  if (player.portrait) {
    const portraitDisplay = document.getElementById('player-portrait');
    if (portraitDisplay) {
      const testImg = new Image();
      testImg.onload = function() {
        portraitDisplay.src = player.portrait;
        portraitDisplay.style.display = 'block';
      };
      testImg.onerror = function() {
        portraitDisplay.style.display = 'none';
      };
      testImg.src = player.portrait;
    }
  }

  // Emit state change events (pub/sub)
  const dirty = (player.dirtyMoney || 0);
  try {
    if (window.EventBus) {
      if (!window.__lastEventSnapshot) {
        window.__lastEventSnapshot = {
          money: player.money,
          dirtyMoney: dirty,
          reputation: player.reputation,
          heat: player.heat,
          health: player.health,
          inJail: player.inJail,
          jailTime: player.jailTime,
          territoryCount: (player.turf?.owned || []).length,
          level: player.level,
          experience: player.experience
        };
      }
      const snap = window.__lastEventSnapshot;
      const emitNum = (key, value, evt) => {
        const old = snap[key];
        if (old !== value) {
          EventBus.emit(evt, { oldValue: old, newValue: value });
          snap[key] = value;
        }
      };
      if (snap.inJail !== player.inJail) {
        EventBus.emit('jailStatusChanged', { inJail: player.inJail, jailTime: player.jailTime });
        snap.inJail = player.inJail;
      }
      if (snap.jailTime !== player.jailTime) {
        EventBus.emit('jailTimeUpdated', { jailTime: player.jailTime });
        snap.jailTime = player.jailTime;
      }
      emitNum('money', player.money, 'moneyChanged');
      emitNum('dirtyMoney', dirty, 'dirtyMoneyChanged');
      emitNum('reputation', Math.floor(player.reputation), 'reputationChanged');
      emitNum('heat', player.heat, 'heatChanged');
      emitNum('health', player.health, 'healthChanged');
      emitNum('territoryCount', (player.turf?.owned || []).length, 'territoryChanged');
      emitNum('level', player.level, 'levelChanged');
    }
  } catch (e) { console.warn('HUD snapshot emit error:', e); }

  // Check for newly unlocked menu items
  checkForNewUnlocks();

  // Money and heat HUD updates handled via EventBus subscribers

  // Update dirty money display in stats bar (always visible)
  const dirtyMoneyDisplay = document.getElementById('dirty-money-display');
  if (dirtyMoneyDisplay) {
    const dirtyAmount = player.dirtyMoney || 0;
    dirtyMoneyDisplay.innerText = `Dirty: $${dirtyAmount.toLocaleString()}`;
  }

  document.getElementById('power-display').innerText = `Power: ${player.power}`;

  // Add turf display with next tribute countdown
  const turfDisplay = document.getElementById('turf-display');
  if (turfDisplay) {
    const ownedCount = (player.turf?.owned || []).length;
    const hasGang = player.gang && (player.gang.gangMembers && player.gang.gangMembers.length > 0);
    const hasBusinesses = player.businesses && player.businesses.length > 0;
    const hasRackets = player.protectionRackets && player.protectionRackets.length > 0;
    const hasTurf = ownedCount > 0;

    if (hasTurf || hasGang || hasBusinesses || hasRackets) {
      const now = Date.now();
      let soonestSec = Infinity;
      let allReady = true;

      // Gang tribute: 5 min (300s) cooldown
      if (hasGang) {
        const gangElapsed = (now - (player.gang.lastTributeTime || 0)) / 1000;
        if (gangElapsed < 300) { allReady = false; soonestSec = Math.min(soonestSec, 300 - gangElapsed); }
      }

      // Turf tribute: 60 min cooldown
      if (hasTurf) {
        const turfElapsed = (now - (player.turf.lastTributeCollection || 0)) / 1000;
        if (turfElapsed < 3600) { allReady = false; soonestSec = Math.min(soonestSec, 3600 - turfElapsed); }
      }

      // Business income: 60 min accrual
      if (hasBusinesses) {
        player.businesses.forEach(biz => {
          const bizElapsed = (now - (biz.lastCollection || now)) / 1000;
          if (bizElapsed < 3600) { allReady = false; soonestSec = Math.min(soonestSec, 3600 - bizElapsed); }
        });
      }

      // Protection rackets: 24 hour cooldown
      if (hasRackets) {
        const rackCD = 24 * 3600;
        player.protectionRackets.forEach(r => {
          const rElapsed = (now - (r.lastCollection || 0)) / 1000;
          if (rElapsed < rackCD) { allReady = false; soonestSec = Math.min(soonestSec, rackCD - rElapsed); }
        });
      }

      let tributeText;
      if (allReady) {
        tributeText = 'Next Tribute: Ready';
      } else {
        const sec = Math.ceil(soonestSec);
        if (sec >= 86400) {
          const d = Math.floor(sec / 86400);
          const h = Math.floor((sec % 86400) / 3600);
          tributeText = `Next Tribute: ${d}d ${h}h`;
        } else if (sec >= 3600) {
          const h = Math.floor(sec / 3600);
          const m = Math.floor((sec % 3600) / 60);
          tributeText = `Next Tribute: ${h}h ${m}m`;
        } else {
          const m = Math.floor(sec / 60);
          const s = sec % 60;
          tributeText = `Next Tribute: ${m}:${String(s).padStart(2, '0')}`;
        }
      }
      turfDisplay.innerText = tributeText;
      turfDisplay.style.display = 'block';
    } else {
      turfDisplay.style.display = 'none';
    }
  }

  // Update current district display (multiplayer district system)
  const curTerritoryDisplay = document.getElementById('current-territory-display');
  if (curTerritoryDisplay) {
    if (player.currentTerritory) {
      const td = getDistrict(player.currentTerritory);
      if (td) {
        curTerritoryDisplay.innerText = `${td.icon} ${td.shortName}`;
        curTerritoryDisplay.style.display = 'block';
      }
    } else {
      curTerritoryDisplay.style.display = 'none';
    }
  }

  document.getElementById('health-display').innerText = `Health: ${player.health}`;

  // Update Empire Rating (passive calculation)
  calculateEmpireRating();

  // Add new UI elements if they exist
  if (document.getElementById('level-display')) {
    const tier = getReputationTier(player.reputation);
    document.getElementById('level-display').innerText = `Rank: ${tier.name}`;
  }

  if (document.getElementById('skill-points-display')) {
    if (player.activeTraining) {
      const t = player.activeTraining;
      const remaining = Math.max(0, t.duration - (Date.now() - t.startTime));
      const sec = Math.ceil(remaining / 1000);
      const nodeDef = SKILL_TREE_DEFS[t.tree]?.nodes[t.node];
      document.getElementById('skill-points-display').innerText = `Training: ${nodeDef?.name || t.node} (${formatTrainingTime(sec)})`;
    } else if (player.activeHealing) {
      const h = player.activeHealing;
      const remaining = Math.max(0, h.duration - Math.floor((Date.now() - h.startTime) / 1000));
      document.getElementById('skill-points-display').innerText = `Healing: ${remaining}s remaining`;
    } else {
      document.getElementById('skill-points-display').innerText = 'Training: Idle';
    }
  }
  if (document.getElementById('season-display')) {
    document.getElementById('season-display').innerText = `Season: ${currentSeason}`;
  }

  // Update weather HUD
  const weatherDisplay = document.getElementById('weather-display');
  if (weatherDisplay) {
    const weather = weatherEffects[currentWeather];
    if (weather) {
      weatherDisplay.innerText = `Weather: ${weather.icon} ${weather.name}`;
    }
  }

  // Update active events HUD
  const eventsDisplay = document.getElementById('active-events-display');
  if (eventsDisplay) {
    if (activeEvents && activeEvents.length > 0) {
      const eventNames = activeEvents.map(e => `${e.icon || ''} ${e.name}`).join(', ');
      eventsDisplay.innerText = `Events: ${eventNames}`;
      eventsDisplay.style.display = 'block';
    } else {
      eventsDisplay.style.display = 'none';
    }
  }

  // Update ammo / gas / reputation HUD elements
  const ammoDisplay = document.getElementById('ammo-display');
  if (ammoDisplay) {
    ammoDisplay.innerText = `Bullets: ${player.ammo || 0}`;
  }
  const gasDisplay = document.getElementById('gas-display');
  if (gasDisplay) {
    gasDisplay.innerText = `Gas: ${player.gas || 0}`;
  }
  const reputationDisplay = document.getElementById('reputation-display');
  if (reputationDisplay) {
    reputationDisplay.innerText = `Respect: ${Math.floor(player.reputation)}`;
  }
  const jailStatusDisplay = document.getElementById('jail-status-display');
  if (jailStatusDisplay) {
    jailStatusDisplay.innerText = player.inJail ? `Jail: ${player.jailTime}s` : 'Jail: Free';
  }
  const familyRankDisplay = document.getElementById('family-rank-display');
  if (familyRankDisplay) {
    if (player.chosenFamily) {
      const famLabels = { torrino: 'Torrino', kozlov: 'Kozlov', chen: 'Chen', morales: 'Morales' };
      const rankLabel = player.familyRank ? player.familyRank.charAt(0).toUpperCase() + player.familyRank.slice(1) : 'Associate';
      familyRankDisplay.innerText = `${famLabels[player.chosenFamily] || player.chosenFamily} -- ${rankLabel}`;
    } else {
      familyRankDisplay.innerText = 'Family: None';
    }
  }

  // Apply user stat-bar visibility preferences (hides toggled-off stats)
  applyStatBarPrefs();

  updateRightPanelExtras();
  updateQuickActions();

  // If player is in jail, just update the jail-specific UI elements (timer, buttons)
  // without calling showJailScreen() which does hideAllScreens() → scrollTo(0,0).
  // showJailScreen() is called explicitly by sendToJail() and game-load only.
  if (player.inJail) {
    updateJailUI();
  }

  // Refresh current screen if it depends on money/stats
  refreshCurrentScreen();

  // Check for achievements
  checkAchievements();
  // Recalculate empire rating
  calculateEmpireRating();
  // Check weekly challenges (less frequent)
  if (Math.random() < 0.1) { // 10% chance per UI update to avoid too frequent checks
    checkWeeklyChallenges();
  }


}

