// Toggle tutorials from Settings screen
function toggleTutorialFromSettings() {
  if (localStorage.getItem('tutorialSkipAll') === '1') {
    reEnableContextualTutorials();
  } else {
    skipAllTutorials();
  }
  syncTutorialToggleButton();
  updateQuickActions();
}
window.toggleTutorialFromSettings = toggleTutorialFromSettings;

// Sync the tutorial toggle button state on the Settings screen
function syncTutorialToggleButton() {
  const btn = document.getElementById('tutorial-toggle-btn');
  if (!btn) return;
  const skipped = localStorage.getItem('tutorialSkipAll') === '1';
  const mode = getTutorialMode();
  if (skipped) {
    btn.textContent = 'Tutorials: Disabled';
    btn.style.borderColor = '#8b3a3a';
    btn.style.color = '#8b3a3a';
  } else if (mode === 'contextual') {
    btn.textContent = 'Tutorials: Learn as You Play';
    btn.style.borderColor = '#8a9a6a';
    btn.style.color = '#8a9a6a';
  } else {
    btn.textContent = 'Tutorials: Enabled';
    btn.style.borderColor = '#8a9a6a';
    btn.style.color = '#8a9a6a';
  }
}
window.syncTutorialToggleButton = syncTutorialToggleButton;

// Auto-sync .screen-active class with display state so CSS can hide
// fixed-position page-headers inside inactive screens (mobile ghost fix).
(function setupScreenActiveObserver() {
  const observer = new MutationObserver(mutations => {
    for (const m of mutations) {
      if (m.type === 'attributes' && m.attributeName === 'style') {
        const el = m.target;
        if (el.classList.contains('game-screen')) {
          if (el.style.display === 'block') {
            el.classList.add('screen-active');
          } else {
            el.classList.remove('screen-active');
          }
        }
      }
    }
  });
  // Observe all game-screens once DOM is ready
  const startObserving = () => {
    document.querySelectorAll('.game-screen').forEach(screen => {
      observer.observe(screen, { attributes: true, attributeFilter: ['style'] });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', startObserving);
  } else {
    startObserving();
  }
})();

// Function to show jobs
const JOB_REP_BY_RISK = { low: 1, medium: 1.8, high: 3.5, 'very high': 5, extreme: 8, legendary: 12 };

function showJobs() {
  if (player.inJail) {
    showBriefNotification("You can't work while you're in jail!", 'danger');
    return;
  }

  // Sort jobs: available first, then cooldown, then locked
  const sortedJobs = jobs.map((job, index) => {
    const hasReqs = hasRequiredItems(job.requiredItems);
    const cd = getJobCooldownRemaining(index);
    const priority = !hasReqs ? 2 : cd > 0 ? 1 : 0;
    return { job, index, priority };
  });
  sortedJobs.sort((a, b) => a.priority - b.priority);

  let jobListHTML = `
    <h3>Available Jobs</h3>
    <ul>
      ${sortedJobs.map(({ job, index }) => {
        const hasItems = hasRequiredItems(job.requiredItems);
        const hasRequirements = hasItems;

        // Check cooldown status
        const cooldownRemaining = getJobCooldownRemaining(index);

        let payoutText = '';
        if (job.special === 'car_theft') {
          payoutText = 'Steal random car to sell';
        } else if (job.paysDirty) {
          payoutText = `<span style="color:#8b3a3a;">$${job.payout[0].toLocaleString()} to $${job.payout[1].toLocaleString()} (DIRTY MONEY)</span>`;
        } else {
          payoutText = `$${job.payout[0].toLocaleString()} to $${job.payout[1].toLocaleString()}`;
        }

        let buttonColor = 'green';
        let buttonText = 'Work';
        let isDisabled = false;

        if (!hasRequirements) {
          buttonColor = 'red';
          buttonText = 'Requirements Not Met';
          isDisabled = true;
        } else if (cooldownRemaining > 0) {
          buttonColor = 'orange';
          buttonText = formatCooldownTime(cooldownRemaining);
          isDisabled = true;
        } else if (job.risk === 'legendary') {
          buttonColor = '#8b6a4a';
          buttonText = 'Legendary Hit';
        } else if (job.risk === 'extreme') {
          buttonColor = '#7a2a2a';
          buttonText = 'Go All In';
        } else if (job.risk === 'very high') {
          buttonColor = '#e67e22';
          buttonText = 'High Stakes';
        } else if (job.risk === 'high') {
          buttonColor = 'gold';
          buttonText = 'Execute';
        }

        const baseCooldown = getJobCooldown(job);
        const cooldownLabel = cooldownRemaining > 0
          ? `<span style="color:#e67e22;">${formatCooldownTime(cooldownRemaining)}</span>`
          : '<span style="color:#8a9a6a;">Ready</span>';

        // Build inline details visible without hover
        let detailParts = [];
        if (job.requiresBusiness) {
          const hasBiz = player.businesses && player.businesses.length > 0;
          const color = hasBiz ? '#8a9a6a' : '#ff6b6b';
          const icon = hasBiz ? '\u2713' : '\u2717';
          detailParts.push(`<span style="color:${color};">${icon} Business Front</span>`);
        }
        if (job.requiredItems.length > 0) {
          const itemParts = job.requiredItems.map(item => {
            const hasIt = player.inventory && player.inventory.some(inv => inv.name === item);
            const color = hasIt ? '#8a9a6a' : '#ff6b6b';
            const icon = hasIt ? '\u2713' : '\u2717';
            return `<span style="color:${color};">${icon} ${item}</span>`;
          });
          detailParts.push(...itemParts);
        }
        let detailsHTML = '';
        if (detailParts.length > 0) {
          detailsHTML += `<br><small style="line-height:1.6;">${detailParts.join(' &nbsp; ')}</small>`;
        }
        detailsHTML += `<br><small style="color:#8a7a5a;">Jail: ${getDisplayJailChance(job.jailChance)}% | Damage: ${job.healthLoss} | Heat: +${job.heatGain} | Respect: <span style="color:#c0a062;">${JOB_REP_BY_RISK[job.risk] || 0.5}</span></small>`;

        return `
          <li class="game-card game-card--accent-left" style="--card-accent: ${buttonColor};">
            <strong class="game-card__title">${job.name}</strong> - ${payoutText}
            <br><small>Risk: ${job.risk.toUpperCase()} | Cooldown: ${formatCooldownTime(baseCooldown)} | ${cooldownLabel}</small>
            ${detailsHTML}
            <button data-job-index="${index}" style="background-color: ${buttonColor};"
                onclick="startJob(${index})"
                ${isDisabled ? 'disabled' : ''}>
              ${buttonText}
            </button>
          </li>
        `;
      }).join('')}
    </ul>
  `;

  document.getElementById('job-list').innerHTML = jobListHTML;
  hideAllScreens();
  document.getElementById('jobs-screen').style.display = 'block';
}

// Function to log actions
// Remove emojis from UI strings
function stripEmoji(str) {
  if (!str) return str;
  try {
    return str
      .replace(/\p{Extended_Pictographic}/gu, '')
      .replace(/\uFE0F/gu, '')
      .replace(/[\u2600-\u27BF]/g, '');
  } catch (e) {
    return str.replace(/[\u{1F300}-\u{1FAFF}\u{1F1E6}-\u{1F1FF}\u{1F900}-\u{1F9FF}\u{2600}-\u{27BF}]/gu, '');
  }
}

// Format money to short form (e.g., 1500 -> 1.5K, 1500000 -> 1.5M)
function formatShortMoney(amount) {
  if (typeof amount !== 'number' || isNaN(amount)) return amount;
  if (amount >= 1000000) {
    const val = Math.round((amount / 1000000) * 10) / 10;
    return (val % 1 === 0 ? val.toFixed(0) : val.toFixed(1)) + 'M';
  }
  if (amount >= 1000) {
    const val = Math.round((amount / 1000) * 10) / 10;
    return (val % 1 === 0 ? val.toFixed(0) : val.toFixed(1)) + 'K';
  }
  return amount.toLocaleString();
}

// ==================== LEDGER FILTER SYSTEM ====================
// Tracks which category of log entries to show: 'all', 'environment', 'chat'
let currentLedgerFilter = 'all';

function setLedgerFilter(filter) {
  currentLedgerFilter = filter;

  // Update active button state
  document.querySelectorAll('.ledger-filter-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-filter') === filter);
  });

  // Show/hide log items based on category
  const logList = document.getElementById('log-list');
  if (!logList) return;
  Array.from(logList.children).forEach(li => {
    const cat = li.getAttribute('data-log-category') || 'environment';
    if (filter === 'all') {
      li.style.display = '';
    } else if (filter === 'chat') {
      // 'chat' filter also shows 'online' entries (connection/disconnect messages)
      li.style.display = (cat === 'chat' || cat === 'online') ? '' : 'none';
    } else {
      li.style.display = (cat === filter) ? '' : 'none';
    }
  });

  // Scroll to the newest visible entry
  const visible = logList.querySelector('li:not([style*="display: none"]):last-child') ||
                  logList.querySelector('li:not([style*="display: none"])');
  if (visible) visible.scrollIntoView({ behavior: 'smooth' });
}
window.setLedgerFilter = setLedgerFilter;

// Formats a timestamp into relative text ("just now", "2m ago", etc.)
function formatRelativeTime(timestamp) {
  const diff = Math.floor((Date.now() - timestamp) / 1000);
  if (diff < 10) return 'just now';
  if (diff < 60) return `${diff}s ago`;
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
  if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
  return `${Math.floor(diff / 86400)}d ago`;
}

// Periodically refresh all visible timestamps in the ledger
setInterval(() => {
  const items = document.querySelectorAll('#log-list li[data-log-time]');
  items.forEach(li => {
    const ts = parseInt(li.getAttribute('data-log-time'), 10);
    const span = li.querySelector('.log-timestamp');
    if (span && ts) span.textContent = formatRelativeTime(ts);
  });
}, 30000); // every 30s

// Strips HTML tags to get a plain-text key for grouping
function _logPlainText(msg) {
  const tmp = document.createElement('span');
  tmp.innerHTML = msg;
  return tmp.textContent || tmp.innerText || '';
}

function logAction(message, category) {
  const cat = category || 'environment';
  const logList = document.getElementById('log-list');
  const now = Date.now();

  // --- Grouping: if latest entry has same category + text, bump its count ---
  const lastItem = logList.lastElementChild;
  if (lastItem && cat !== 'chat' && cat !== 'online') {
    const lastMsg = lastItem.getAttribute('data-log-msg') || '';
    const plainMsg = _logPlainText(message);
    if (lastMsg === plainMsg && lastItem.getAttribute('data-log-category') === cat) {
      const count = parseInt(lastItem.getAttribute('data-log-count') || '1', 10) + 1;
      lastItem.setAttribute('data-log-count', count);
      lastItem.setAttribute('data-log-time', now);
      let badge = lastItem.querySelector('.log-group-count');
      if (!badge) {
        badge = document.createElement('span');
        badge.className = 'log-group-count';
        const msgSpan = lastItem.querySelector('.log-msg');
        if (msgSpan) msgSpan.appendChild(badge);
      }
      badge.textContent = `x${count}`;
      const tsSpan = lastItem.querySelector('.log-timestamp');
      if (tsSpan) tsSpan.textContent = formatRelativeTime(now);
      if (lastItem.style.display !== 'none') {
        lastItem.scrollIntoView({ behavior: 'smooth' });
      }
      updateMobileActionLog();
      return;
    }
  }

  // --- Create new entry ---
  const logItem = document.createElement('li');
  logItem.setAttribute('data-log-category', cat);
  logItem.setAttribute('data-log-time', now);
  logItem.setAttribute('data-log-msg', _logPlainText(message));

  const msgSpan = document.createElement('span');
  msgSpan.className = 'log-msg';
  msgSpan.innerHTML = message;
  logItem.appendChild(msgSpan);

  const tsSpan = document.createElement('span');
  tsSpan.className = 'log-timestamp';
  tsSpan.textContent = 'just now';
  logItem.appendChild(tsSpan);

  // Style chat entries differently
  if (cat === 'chat') {
    logItem.style.borderLeftColor = '#c0a062';
  } else if (cat === 'online') {
    logItem.style.borderLeftColor = '#8b6a4a';
  }

  // Respect current filter
  if (currentLedgerFilter !== 'all' && cat !== currentLedgerFilter) {
    if (!(currentLedgerFilter === 'chat' && cat === 'online')) {
      logItem.style.display = 'none';
    }
  }

  logList.appendChild(logItem);

  // Cap log at 200 entries to avoid memory bloat
  while (logList.children.length > 200) {
    logList.removeChild(logList.firstChild);
  }

  if (logItem.style.display !== 'none') {
    logItem.scrollIntoView({ behavior: 'smooth' });
  }

  updateMobileActionLog();
}

// Advanced Skills Integration Functions

function trackJobPlaystyle(job, success = true) {
  if (!success) return; // Only track successful jobs for playstyle

  // Determine job type and update playstyle stats
  const jobName = job.name.toLowerCase();

  if (jobName.includes('stealth') || jobName.includes('sneak') || jobName.includes('infiltrat') ||
    jobName.includes('pickpocket') || jobName.includes('burglar')) {
    player.playstyleStats.stealthyJobs = (player.playstyleStats.stealthyJobs || 0) + 1;
  }

  if (jobName.includes('fight') || jobName.includes('rob') || jobName.includes('assault') ||
    jobName.includes('extort') || jobName.includes('intimidat') || jobName.includes('violent')) {
    player.playstyleStats.violentJobs = (player.playstyleStats.violentJobs || 0) + 1;
  }

  if (jobName.includes('negotiate') || jobName.includes('bribe') || jobName.includes('charm') ||
    jobName.includes('persuad') || jobName.includes('diplomat')) {
    player.playstyleStats.diplomaticActions = (player.playstyleStats.diplomaticActions || 0) + 1;
  }

  if (jobName.includes('hack') || jobName.includes('cyber') || jobName.includes('digital') ||
    jobName.includes('computer') || jobName.includes('tech')) {
    player.playstyleStats.hackingAttempts = (player.playstyleStats.hackingAttempts || 0) + 1;
  }
}

function applySkillTreeBonuses(job, _successChance) {
  let bonuses = 0;
  const jobName = job.name.toLowerCase();

  // Apply skill tree bonuses based on job type
  if (jobName.includes('stealth') || jobName.includes('sneak')) {
    bonuses += player.skillTree.stealth.infiltration * 5; // 5% per level
    bonuses += player.skillTree.stealth.surveillance * 4; // 4% per level
  }

  if (jobName.includes('fight') || jobName.includes('rob') || jobName.includes('assault') ||
    jobName.includes('protection') || jobName.includes('extortion') || jobName.includes('heist')) {
    bonuses += player.skillTree.combat.firearms * 6; // 6% per level
    bonuses += player.skillTree.combat.melee_mastery * 4; // 4% per level
  }

  if (jobName.includes('negotiate') || jobName.includes('bribe')) {
    bonuses += player.skillTree.charisma.negotiation * 3; // 3% per level
    bonuses += player.skillTree.charisma.manipulation * 4; // 4% per level
  }

  if (jobName.includes('hack') || jobName.includes('cyber') || jobName.includes('heist') ||
    jobName.includes('plan') || jobName.includes('intel')) {
    bonuses += player.skillTree.intelligence.hacking * 7; // 7% per level
    bonuses += player.skillTree.intelligence.planning * 4; // 4% per level
    bonuses += player.skillTree.intelligence.forensics * 3; // 3% per level - helps with clean execution
  }

  return Math.min(bonuses, 50); // Cap at 50% bonus
}

function updateFactionReputation(job, success) {
  if (!success) return;

  const jobName = job.name.toLowerCase();
  let reputationChanges = {};

  // Different jobs affect different factions
  if (jobName.includes('italian') || jobName.includes('pizza') || jobName.includes('restaurant')) {
    reputationChanges.torrino = success ? 1 : -2;
  }

  if (jobName.includes('russian') || jobName.includes('vodka') || jobName.includes('bratva')) {
    reputationChanges.kozlov = success ? 1 : -2;
  }

  if (jobName.includes('chinese') || jobName.includes('triad') || jobName.includes('chinatown')) {
    reputationChanges.chen = success ? 1 : -2;
  }

  if (jobName.includes('cartel') || jobName.includes('drug') || jobName.includes('border')) {
    reputationChanges.morales = success ? 1 : -2;
  }

  // Police reputation changes based on job visibility
  if (job.heatGain > 2) {
    reputationChanges.police = -1; // High-profile crimes hurt police relations
  }

  // Apply reputation changes -- keep both streetReputation and missions.factionReputation in sync
  Object.entries(reputationChanges).forEach(([faction, change]) => {
    if (player.streetReputation[faction] !== undefined) {
      player.streetReputation[faction] = Math.max(-100, Math.min(100,
        player.streetReputation[faction] + change));
    }
    // Sync to missions.factionReputation so passives, empire overview, and achievements work
    if (player.missions?.factionReputation && player.missions.factionReputation[faction] !== undefined) {
      player.missions.factionReputation[faction] = Math.max(0, Math.min(100,
        (player.missions.factionReputation[faction] || 0) + Math.max(0, change)));
    }
  });
}

// checkForNewPerks removed -- Phase 31

// getReputationPriceModifier removed -- redundant with getStreetRepBonus('underground', ...) in buyItem()

// Check if the player has a specific utility item in their inventory
function hasUtilityItem(name) {
  return player.inventory && player.inventory.some(i => i.name === name);
}

// Function to start a job
async function startJob(index) {
  if (player.inJail) {
    showBriefNotification("You can't work while you're in jail!", 'danger');
    return;
  }

  let job = jobs[index];

  // Get active events and weather effects early
  const activeEffects = getActiveEffects();

  // Check if job is on cooldown
  const cooldownRemaining = getJobCooldownRemaining(index);
  if (cooldownRemaining > 0) {
    showBriefNotification(`This job is on cooldown! Available in ${formatCooldownTime(cooldownRemaining)}.`, 'danger');
    return;
  }

  // Check if the player has required items
  if (!hasRequiredItems(job.requiredItems)) {
    showBriefNotification(`You need the following items to perform this job: ${job.requiredItems.join(', ')}`, 'danger');
    return;
  }

  // Check if the job requires owning a business (front property)
  if (job.requiresBusiness && (!player.businesses || player.businesses.length === 0)) {
    showBriefNotification('You need to own at least one business front to run this operation. Buy a property first!', 'danger');
    return;
  }

  // Crew check for risky jobs
  if (job.risk === 'high' || job.risk === 'very high') {
    const crewChoice = await checkCrewBeforeAction(job.name, true);
    if (crewChoice === 'crew' || crewChoice === 'cancel') return;
  }

  // ---- JOB DEPTH: Approach choices for mid & elite tier jobs ----
  let approachBonus = 0;
  let approachLabel = '';

  if (job.risk === 'high' || job.risk === 'very high') {
    // Mid-tier: choose approach -- "Go Loud" or "Stay Quiet"
    const modal = new ModalSystem();
    const choice = await modal.show(
      `Plan the ${job.name}`,
      `<p>This is a <strong>${job.risk.toUpperCase()}</strong> risk job. How do you want to play it?</p>
       <p style="color:#8b3a3a;"><strong>Go Loud</strong> -- Brute force. Higher success using <em>violence</em>, but more heat & damage risk.</p>
       <p style="color:#c0a062;"><strong>Stay Quiet</strong> -- Stealth approach. Higher success using <em>stealth</em>, but lower payout if things go sideways.</p>`,
      [
        { text: 'Go Loud', class: 'modal-btn-primary', value: 'loud', callback: () => true },
        { text: 'Stay Quiet', class: 'modal-btn-secondary', value: 'quiet', callback: () => true },
        { text: 'Abort', class: 'modal-btn-secondary', value: 'abort', callback: () => true }
      ]
    );

    if (!choice || choice === 'abort') return;

    if (choice === 'loud') {
      approachBonus = player.skillTree.combat.brawler * 3;
      approachLabel = 'Loud';
      logAction(`You gear up for a loud approach on the ${job.name}. Violence is your friend today.`);
    } else {
      approachBonus = player.skillTree.stealth.shadow_step * 3;
      approachLabel = 'Quiet';
      logAction(` You plan a stealthy approach for the ${job.name}. Patience is key.`);
    }
  } else if (job.risk === 'extreme' || job.risk === 'legendary') {
    // Elite-tier: briefing panel with crew & vehicle readiness + approach choice
    const gangReady = player.gang.members >= 3;
    const carReady = player.selectedCar !== null && player.selectedCar < player.stolenCars.length;
    const gangStatus = gangReady
      ? `<span style="color:#8a9a6a;">&#10004; ${player.gang.members} soldiers standing by</span>`
      : `<span style="color:#8b3a3a;">&#10008; Need at least 3 gang members (have ${player.gang.members})</span>`;
    const carStatus = carReady
      ? `<span style="color:#8a9a6a;">&#10004; Getaway vehicle selected: ${player.stolenCars[player.selectedCar].name}</span>`
      : '<span style="color:#e67e22;">&#10008; No getaway vehicle selected (optional but recommended)</span>';

    const modal = new ModalSystem();
    const choice = await modal.show(
      `${job.risk.toUpperCase()} BRIEFING: ${job.name}`,
      `<div style="padding:8px;">
        <p>This is a <strong style="color:#8b6a4a;">${job.risk.toUpperCase()}</strong> operation. Review your readiness:</p>
        <div style="margin:10px 0; padding:10px; background:rgba(0,0,0,0.3); border-radius:5px;">
          <strong>Crew:</strong> ${gangStatus}<br>
          <strong>Vehicle:</strong> ${carStatus}<br>
          <strong>Your Power:</strong> ${player.power} | <strong>Health:</strong> ${player.health}
        </div>
        <p style="margin-top:10px;">Choose your approach:</p>
        <p style="color:#8b3a3a;"><strong>Go Loud</strong> -- Full assault. Higher payout, more heat & damage risk.</p>
        <p style="color:#c0a062;"><strong>Stay Quiet</strong> -- Calculated precision. Lower heat, better conversion, reduced risk.</p>
       </div>`,
      [
        { text: 'Go Loud', class: 'modal-btn-primary', value: 'loud', callback: () => true },
        { text: 'Stay Quiet', class: 'modal-btn-secondary', value: 'quiet', callback: () => true },
        { text: 'Stand Down', class: 'modal-btn-secondary', value: 'abort', callback: () => true }
      ]
    );

    if (!choice || choice === 'abort') return;

    // Crew bonus for elite jobs
    if (gangReady) {
      approachBonus = Math.min(player.gang.members * 2, 20); // Up to +20% from crew
      logAction(`Your crew of ${player.gang.members} rolls out with you -- strength in numbers.`);
    }

    if (choice === 'loud') {
      approachBonus += player.skillTree.combat.brawler * 3;
      approachLabel = 'Loud';
      logAction(`You gear up heavy for the ${job.name}. No subtlety today -- raw firepower.`);
    } else {
      approachBonus += player.skillTree.stealth.shadow_step * 3;
      approachLabel = 'Quiet';
      logAction(`You plan a surgical approach for the ${job.name}. In. Out. No witnesses.`);
    }
  }

  setJobCooldown(index, job); // Set crime cooldown timer
  startCooldownTick(); // Start the cooldown refresh tick

  // Calculate job success chance based on player's power level and skills
  let successChance;
  let skillBonus = (player.skillTree.intelligence.quick_study * 4 + player.skillTree.luck.fortune) * 2;
  // Awareness: +2% luck-based outcomes per rank
  skillBonus += (player.skillTree.intelligence.awareness || 0) * 2;
  let carBonus = 0;

  // Apply advanced skill tree bonuses
  let advancedBonus = applySkillTreeBonuses(job, 0);

  let eventBonus = 0;

  // Apply event effects to job success
  if (activeEffects.jobSuccessBonus) {
    eventBonus += activeEffects.jobSuccessBonus * 100;
    logAction(`Current events favor your operations (+${(activeEffects.jobSuccessBonus * 100).toFixed(0)}% success chance)!`);
  }

  if (activeEffects.stealthBonus && job.name.toLowerCase().includes('stealth')) {
    eventBonus += activeEffects.stealthBonus * 100;
    logAction('Weather conditions provide excellent cover for stealth operations!');
  }

  if (activeEffects.violentJobBonus && (job.name.toLowerCase().includes('fight') || job.name.toLowerCase().includes('rob'))) {
    eventBonus += activeEffects.violentJobBonus * 100;
    logAction('The current atmosphere makes people more aggressive - perfect for violent jobs!');
  }

  // Equipped vehicle condition bonus
  let vehicleBonus = 0;
  if (player.equippedVehicle && typeof player.equippedVehicle === 'object') {
    const veh = player.equippedVehicle;
    const vCondition = (100 - (veh.vehicleDamage || 0)) / 100;
    // Base bonus scales with vehicle power; condition scales it down
    vehicleBonus = Math.floor((veh.power || 0) * 0.5 * vCondition);
    if (vehicleBonus > 0) {
      logAction(`Your ${veh.name} is in ${Math.round(vCondition * 100)}% condition, boosting your odds (+${vehicleBonus}% success).`);
    }
  }

  // Utility item: Fake ID Kit gives +10% success on all jobs
  let utilityBonus = 0;
  if (hasUtilityItem('Fake ID Kit')) {
    utilityBonus += 10;
    logAction('Your Fake ID Kit keeps you under the radar (+10% success).');
  }

  // Car bonus for jobs (if player has selected a car)
  if (player.selectedCar !== null && player.selectedCar < player.stolenCars.length) {
    let selectedCar = player.stolenCars[player.selectedCar];
    carBonus = Math.floor((selectedCar.baseValue / 100) * (1 - selectedCar.damagePercentage / 100));

    // Apply weather effects to car usage
    if (activeEffects.carAccidents) {
      carBonus = Math.floor(carBonus * (1 - activeEffects.carAccidents));
      logAction('Weather conditions make driving more dangerous - car effectiveness reduced!');
    }

    logAction(`You slide into your ${selectedCar.name}, its familiar rumble giving you confidence. The streets feel different with good wheels beneath you (+${carBonus}% success chance).`);
  }

  if (job.risk === 'low') {
    successChance = 30 + player.power * 0.3 + skillBonus + carBonus + vehicleBonus + advancedBonus + eventBonus + utilityBonus + approachBonus;
  } else if (job.risk === 'medium') {
    successChance = 20 + player.power * 0.2 + skillBonus + carBonus + vehicleBonus + advancedBonus + eventBonus + utilityBonus + approachBonus;
  } else if (job.risk === 'high') {
    successChance = 10 + player.power * 0.1 + skillBonus + carBonus + vehicleBonus + advancedBonus + eventBonus + utilityBonus + approachBonus;
  } else if (job.risk === 'very high') {
    successChance = 5 + player.power * 0.08 + skillBonus + carBonus + vehicleBonus + advancedBonus + eventBonus + utilityBonus + approachBonus;
  } else if (job.risk === 'extreme') {
    successChance = 3 + player.power * 0.05 + skillBonus + carBonus + vehicleBonus + advancedBonus + eventBonus + utilityBonus + approachBonus;
  } else if (job.risk === 'legendary') {
    successChance = 1 + player.power * 0.03 + skillBonus + carBonus + vehicleBonus + advancedBonus + eventBonus + utilityBonus + approachBonus;
  }

  // Cap success chance at 95%
  successChance = Math.min(successChance, 95);

  // Corruption: crimeBonus increases success chance
  const corruptCrimeBonus = getCorruptionBenefit('crimeBonus');
  if (corruptCrimeBonus > 0) {
    successChance = Math.min(95, successChance + corruptCrimeBonus * 100);
  }

  // District benefit: information boosts job success
  if (player.currentTerritory) {
    const infoMult = getDistrictBenefit(player.currentTerritory, 'information');
    if (infoMult > 1) { successChance = Math.min(95, successChance * infoMult); }
  }


  // Random chance for job success
  if (Math.random() * 100 > successChance) {
    // Handle failure with advanced skills considerations
    updateFactionReputation(job, false);
    trackJobPlaystyle(job, false);

    // Varied failure consequences
    const failRoll = Math.random() * 100;
    let failExtra = '';
    if (failRoll < 30) {
      // 30%: Witnesses spotted you -- extra heat
      const extraHeat = 2 + Math.floor(Math.random() * 4);
      player.heat = Math.min(100, (player.heat || 0) + extraHeat);
      failExtra = ` Someone saw your face. +${extraHeat} heat.`;
    } else if (failRoll < 50) {
      // 20%: Roughed up during escape
      const hpLoss = 3 + Math.floor(Math.random() * 8);
      player.health = Math.max(1, player.health - hpLoss);
      failExtra = ` You took a beating getting away. -${hpLoss} HP.`;
      flashHurtScreen();
    } else if (failRoll < 65 && player.money > 100) {
      // 15%: Dropped some cash fleeing
      const lostCash = Math.floor(player.money * (0.01 + Math.random() * 0.03));
      player.money -= lostCash;
      failExtra = ` You dropped $${lostCash.toLocaleString()} scrambling to escape.`;
    }
    // remaining 35-50%: clean failure, no extra penalty

    showBriefNotification(`${getFamilyNarration('jobFailure')} The job went sideways.${failExtra}`, 'danger');
    logAction(getFamilyNarration('jobFailure') + failExtra);
    // Still gain some reputation for trying
    gainExperience(0.1);
    updateUI();
    return;
  }

  // Handle special car theft job
  if (job.special === 'car_theft') {
    handleCarTheft(job);
    updateUI();
    return;
  }

  // Handle special money laundering job -- converts dirty money to clean money
  if (job.special === 'launder_money') {
    // Check dirty money
    if (!player.dirtyMoney || player.dirtyMoney <= 0) {
      showBriefNotification("You don't have any dirty money to launder! Earn dirty money from Bank Jobs or Counterfeiting first.", 'danger');
      updateUI();
      return;
    }
    handleLaunderMoneyJob(job, approachLabel);
    updateUI();
    return;
  }

  let earnings;
  if (Array.isArray(job.payout)) {
    earnings = Math.floor(Math.random() * (job.payout[1] - job.payout[0] + 1)) + job.payout[0];
    // Luck skill can increase earnings
    earnings += Math.floor(earnings * (player.skillTree.luck.fortune * 0.02));
  } else {
    earnings = job.payout;
  }

  // Chen Triad passive: drug/smuggling jobs earn 30% more
  const jn = job.name.toLowerCase();
  if (jn.includes('drug') || jn.includes('smuggl') || jn.includes('dealer') || jn.includes('transport')) {
    const drugMultiplier = getDrugIncomeMultiplier();
    if (drugMultiplier > 1) {
      const bonus = Math.floor(earnings * (drugMultiplier - 1));
      earnings += bonus;
      logAction(`Chen Triad smuggling routes boost your earnings by $${bonus.toLocaleString()}.`);
    }
    // Chen streetReputation: additional drug/smuggle earnings modifier
    const chenDrugMod = getStreetRepBonus('chen', 0.05, 0.10, 0.15, 0.20);
    if (chenDrugMod !== 0) {
      const chenRepBonus = Math.floor(earnings * chenDrugMod);
      earnings = Math.max(1, earnings + chenRepBonus);
    }
  }

  // Drug Lab synergy: owning a Drug Lab boosts drug job payouts by 10-25%
  if (jn.includes('bootleg') || jn.includes('speakeasy') || jn.includes('powder') || jn.includes('drug') || jn.includes('distribution')) {
    if (player.businesses && player.businesses.some(b => b.type === 'druglab')) {
      const drugLab = player.businesses.find(b => b.type === 'druglab');
      const boostPercent = 0.08 + (drugLab.level * 0.035); // 11.5% at Lv1, up to 25.5% at Lv5
      const drugLabBonus = Math.floor(earnings * boostPercent);
      earnings += drugLabBonus;
      logAction(` Your Drug Lab provides better product for distribution -- payout boosted by $${drugLabBonus.toLocaleString()}.`);
    }
  }

  // Kingpin Aura skill: +5% all income per rank
  const kingpinAuraLevel = player.skillTree.charisma?.kingpin_aura || 0;
  if (kingpinAuraLevel > 0) {
    const auraBonus = Math.floor(earnings * kingpinAuraLevel * 0.05);
    earnings += auraBonus;
    if (auraBonus > 0) logAction(`Your kingpin aura commands respect -- your cut is $${auraBonus.toLocaleString()} larger.`);
  }

  // Intimidation skill: +6% bonus earnings on violent jobs per rank
  const intimidationEarnings = player.skillTree.combat?.intimidation || 0;
  if (intimidationEarnings > 0) {
    const violentTags = ['fight', 'rob', 'assault', 'heist', 'hit', 'enforce', 'shakedown', 'extort', 'murder'];
    if (violentTags.some(tag => jn.includes(tag))) {
      const intimBonus = Math.floor(earnings * intimidationEarnings * 0.06);
      earnings += intimBonus;
      if (intimBonus > 0) logAction(`Your reputation terrifies the target -- they hand over $${intimBonus.toLocaleString()} extra without a fight.`);
    }
  }

  // Scavenger skill: +3% bonus loot per rank
  const scavengerLevel = player.skillTree.luck?.scavenger || 0;
  if (scavengerLevel > 0) {
    const scavengerBonus = Math.floor(earnings * scavengerLevel * 0.03);
    earnings += scavengerBonus;
    if (scavengerBonus > 0) logAction(`Your scavenger instincts find extra valuables worth $${scavengerBonus.toLocaleString()}.`);
  }

  // Mastermind synergy (Charisma+Intelligence): +15% job payouts
  const mastermindSynergyBonus = getSynergyBonus('charismaIntel');
  if (mastermindSynergyBonus > 0) {
    const mastermindBonus = Math.floor(earnings * mastermindSynergyBonus);
    earnings += mastermindBonus;
    if (mastermindBonus > 0) logAction(`Your mastermind network maximises the take -- +$${mastermindBonus.toLocaleString()}.`);
  }

  // -- District Benefits applied to job earnings --
  const curDistrict = player.currentTerritory || null;
  if (curDistrict) {
    // drugSales: boost drug-related job payout
    if (jn.includes('drug') || jn.includes('dealer') || jn.includes('distribution') || jn.includes('powder')) {
      const drugSalesMult = getDistrictBenefit(curDistrict, 'drugSales');
      if (drugSalesMult > 1) { earnings = Math.floor(earnings * drugSalesMult); }
    }
    // smuggling: boost smuggling/transport payout
    if (jn.includes('smuggl') || jn.includes('transport') || jn.includes('shipping')) {
      const smugglingMult = getDistrictBenefit(curDistrict, 'smuggling');
      if (smugglingMult > 1) { earnings = Math.floor(earnings * smugglingMult); }
    }
    // theft: boost theft/robbery payout
    if (jn.includes('theft') || jn.includes('steal') || jn.includes('shoplift') || jn.includes('pickpocket') || jn.includes('burglar')) {
      const theftMult = getDistrictBenefit(curDistrict, 'theft');
      if (theftMult > 1) { earnings = Math.floor(earnings * theftMult); }
    }
    // vice: boost vice-related job payout
    if (jn.includes('gambl') || jn.includes('prostit') || jn.includes('vice') || jn.includes('bootleg') || jn.includes('speakeasy')) {
      const viceMult = getDistrictBenefit(curDistrict, 'vice');
      if (viceMult > 1) { earnings = Math.floor(earnings * viceMult); }
    }
    // heistRewards: boost heist payout
    if (jn.includes('heist') || jn.includes('bank job') || jn.includes('vault')) {
      const heistMult = getDistrictBenefit(curDistrict, 'heistRewards');
      if (heistMult > 1) { earnings = Math.floor(earnings * heistMult); }
    }
    // protection: boost protection/extortion payout
    if (jn.includes('protect') || jn.includes('extort') || jn.includes('racket')) {
      const protMult = getDistrictBenefit(curDistrict, 'protection');
      if (protMult > 1) { earnings = Math.floor(earnings * protMult); }
    }
    // networking: small boost to ALL job earnings
    const netMult = getDistrictBenefit(curDistrict, 'networking');
    if (netMult > 1) { earnings = Math.floor(earnings * netMult); }
  }

  // Crew bonus: being in a crew boosts job earnings (+15% per crew member)
  let crewBonusAmount = 0;
  let crewSize = 0;
  if (player.crewId) {
    crewSize = window._myCrewSize || 1;
    if (crewSize > 1) {
      const crewMultiplier = (crewSize - 1) * 0.15; // +15% per additional crew member
      crewBonusAmount = Math.floor(earnings * crewMultiplier);
      earnings += crewBonusAmount;
      logAction(`Your crew of ${crewSize} boosts the take -- +$${crewBonusAmount.toLocaleString()} crew bonus.`);
    }
  }

  // Calculate jail chance with stealth skill reducing it
  let stealthBonus = player.skillTree.stealth.shadow_step * 2;
  stealthBonus += player.skillTree.stealth.escape_artist * 3; // Advanced escape skills
  stealthBonus += player.skillTree.stealth.infiltration * 2; // Advanced infiltration skills

  let adjustedJailChance = Math.max(1, job.jailChance - stealthBonus);

  // Ghost Protocol synergy (Stealth+Intelligence): -20% arrest chance
  const ghostSynergyBonus = getSynergyBonus('stealthIntel');
  if (ghostSynergyBonus > 0) {
    adjustedJailChance = Math.max(1, Math.floor(adjustedJailChance * (1 - ghostSynergyBonus)));
  }

  // Corruption: cases dismissed by a judge
  const corruptDismissal = getCorruptionBenefit('casesDismissed');
  if (corruptDismissal > 0) {
    adjustedJailChance = Math.max(1, Math.floor(adjustedJailChance * (1 - corruptDismissal)));
  }

  // Street Smarts perk: +15% job success (reduces effective jail chance by 15%)
  if (hasPlayerPerk('street_smarts')) {
    adjustedJailChance = Math.max(1, Math.floor(adjustedJailChance * 0.85));
  }

  // Heat-based arrest modifier: low heat = less arrests, high heat = cops actively hunting you
  const heatLevel = player.heat || 0;
  if (heatLevel <= 10) {
    adjustedJailChance = Math.max(1, Math.floor(adjustedJailChance * 0.60));
  } else if (heatLevel <= 25) {
    adjustedJailChance = Math.max(1, Math.floor(adjustedJailChance * 0.80));
  } else if (heatLevel <= 50) {
    // Normal police attention -- no modifier
  } else if (heatLevel <= 75) {
    adjustedJailChance = Math.floor(adjustedJailChance * 1.30) + 5;
  } else {
    adjustedJailChance = Math.floor(adjustedJailChance * 1.60) + 15;
  }
  adjustedJailChance = Math.min(95, adjustedJailChance);

  let jailChance = Math.random() * 100;

  if (jailChance <= adjustedJailChance) {
    // Corruption: raidWarning gives chance to avoid arrest
    const raidWarningChance = getCorruptionBenefit('raidWarning');
    if (raidWarningChance > 0 && Math.random() < raidWarningChance) {
      logAction('Your captain on the payroll tipped you off \u2014 you slipped away before the bust!');
      showBriefNotification('Raid warning! Your corrupt contact saved you from arrest.', 'warning');
    } else {
      // Silk Voice skill: chance to talk your way out of arrest
      const silkVoiceLevel = player.skillTree?.charisma?.silk_voice || 0;
      if (silkVoiceLevel > 0 && Math.random() * 100 < silkVoiceLevel) {
        logAction('Smooth talking gets you off the hook -- the cops let you walk.');
        showBriefNotification('Silk Voice! You talked your way out of arrest.', 'warning');
      } else {
        sendToJail(job.heatGain, { crimeName: job.name, riskLevel: job.risk });
        return;
      }
    }
  }

  // Bank Job vs Counterfeiting: different dirty money mechanics
  if (job.paysDirty) {
    if (job.name === 'Bank Job') {
      // Bank heist: 60% clean (unmarked bills), 40% dirty (dye-packed/serial-tracked)
      const cleanCut = Math.floor(earnings * 0.60);
      const dirtyCut = earnings - cleanCut;
      player.money += cleanCut;
      player.dirtyMoney = (player.dirtyMoney || 0) + dirtyCut;
      const dirtyHeat = 5 + Math.floor(Math.random() * 6); // 5-10 heat (bank heists are loud)
      player.heat = Math.min(100, player.heat + dirtyHeat);
      logAction(`You crack the vault and grab everything. $${cleanCut.toLocaleString()} in unmarked bills, $${dirtyCut.toLocaleString()} in dye-packed bundles that need laundering. The feds will be all over this (+${dirtyHeat} heat).`);
    } else {
      // Counterfeiting: all dirty, but intelligence skills boost the take
      const intBonus = (player.skillTree.intelligence.quick_study || 0) * 0.03 + (player.skillTree.intelligence.forensics || 0) * 0.05;
      const boostedEarnings = Math.floor(earnings * (1 + intBonus));
      player.dirtyMoney = (player.dirtyMoney || 0) + boostedEarnings;
      const dirtyHeat = 2 + Math.floor(Math.random() * 5); // 2-6 heat (quieter operation)
      player.heat = Math.min(100, player.heat + dirtyHeat);
      if (intBonus > 0) {
        logAction(`Your expertise produces convincing bills. $${boostedEarnings.toLocaleString()} in counterfeit notes ready to circulate (+${dirtyHeat} heat). Intelligence bonus: +${Math.round(intBonus * 100)}%.`);
      } else {
        logAction(`The printing press hums. $${boostedEarnings.toLocaleString()} in fake bills need to be moved carefully (+${dirtyHeat} heat).`);
      }
      earnings = boostedEarnings; // Update for display
    }
  } else {
    player.money += earnings;
  }

  // Apply intimidation to reduce heat gain (witnesses too scared to report)
  let heatGain = job.heatGain;

  // Approach consequence: "Go Loud" adds 30% more heat
  if (approachLabel === 'Loud') {
    heatGain = Math.ceil(heatGain * 1.3);
  }

  // Ghost Protocol: -4% heat gain per rank
  const ghostLevel = player.skillTree.stealth.ghost_protocol || 0;
  if (ghostLevel > 0) {
    heatGain = Math.max(1, Math.floor(heatGain * (1 - ghostLevel * 0.04)));
  }

  // Light Feet: -2% heat gain per rank
  const lightFeetLevel = player.skillTree.stealth?.light_feet || 0;
  if (lightFeetLevel > 0) {
    heatGain = Math.max(1, Math.floor(heatGain * (1 - lightFeetLevel * 0.02)));
  }

  // Utility item: Police Scanner reduces heat gain by 20%
  if (hasUtilityItem('Police Scanner')) {
    heatGain = Math.max(1, Math.floor(heatGain * 0.8));
    logAction('Your Police Scanner intercepts radio chatter -- you dodge the heat (+20% heat reduction).');
  }

    // Morales Cartel streetReputation: heat modifier (positive = less heat, negative = more)
  const moralesHeatMod = getStreetRepBonus('morales', 0.05, 0.10, 0.15, 0.20);
  if (moralesHeatMod !== 0) {
    heatGain = Math.max(1, Math.floor(heatGain * (1 - moralesHeatMod)));
  }

  // Morales Cartel passive: violent crimes generate 20% less heat
  if (job.name && (job.name.toLowerCase().includes('fight') || job.name.toLowerCase().includes('rob') ||
      job.name.toLowerCase().includes('assault') || job.name.toLowerCase().includes('heist'))) {
    const heatMultiplier = getViolenceHeatMultiplier();
    if (heatMultiplier < 1) {
      heatGain = Math.max(1, Math.floor(heatGain * heatMultiplier));
    }
  }

  // Chosen family buffs on heat reduction
  const heatFamilyBuff = getChosenFamilyBuff();
  if (heatFamilyBuff) {
    // Torrino Omerta: -20% heat from ALL jobs
    if (heatFamilyBuff.heatReduction) {
      heatGain = Math.max(1, Math.floor(heatGain * (1 - heatFamilyBuff.heatReduction)));
    }
    // Morales Cartel Supply Line: violent jobs generate 25% less heat
    if (heatFamilyBuff.violentHeatReduction && job.name &&
        (job.name.toLowerCase().includes('fight') || job.name.toLowerCase().includes('rob') ||
         job.name.toLowerCase().includes('assault') || job.name.toLowerCase().includes('heist'))) {
      heatGain = Math.max(1, Math.floor(heatGain * (1 - heatFamilyBuff.violentHeatReduction)));
    }
  }

  // Corruption: bribed officials reduce heat gain
  const corruptHeatReduction = Math.max(getCorruptionBenefit('heatReduction'), getCorruptionBenefit('cityWideProtection'));
  if (corruptHeatReduction > 0) {
    heatGain = Math.max(1, Math.floor(heatGain * (1 - corruptHeatReduction)));
  }

  // District benefits: heatReduction and legitimacy lower heat gain
  if (curDistrict) {
    const distHeatRed = getDistrictBenefit(curDistrict, 'heatReduction', 0);
    if (distHeatRed > 0) { heatGain = Math.max(1, Math.floor(heatGain * (1 - distHeatRed))); }
    const distLegitimacy = getDistrictBenefit(curDistrict, 'legitimacy');
    if (distLegitimacy > 1) { heatGain = Math.max(1, Math.floor(heatGain / distLegitimacy)); }
  }

  player.heat += heatGain;

  // Every 5 clean jobs reduces heat slightly (laying low)
  if (_jobsWithoutArrest > 0 && _jobsWithoutArrest % 5 === 0) {
    player.heat = Math.max(0, player.heat - 2);
    logAction('Staying clean pays off -- heat drops slightly (-2).');
  }

  // Log Ghost Protocol / Light Feet heat reduction
  if ((ghostLevel > 0 || lightFeetLevel > 0) && heatGain < job.heatGain) {
    logAction(' Your shadow training helps you move unnoticed -- less heat from this job.');
  }

  // Apply forensics skill for evidence cleanup
  if (player.skillTree.intelligence.forensics > 0) {
    let forensicsSuccess = Math.random() * 100;
    let forensicsChance = player.skillTree.intelligence.forensics * 8; // 8% chance per level
    // Corruption: evidenceDestruction stacks with forensics
    const corruptEvidence = getCorruptionBenefit('evidenceDestruction');
    if (corruptEvidence > 0) {
      forensicsChance += corruptEvidence * 100;
    }

    if (forensicsSuccess < forensicsChance) {
      let evidenceReduction = Math.min(2, Math.floor(player.skillTree.intelligence.forensics / 3)); // 1-2 heat reduction
      player.heat = Math.max(0, player.heat - evidenceReduction);
      logAction(` Your forensics expertise helps you clean up evidence, reducing heat by ${evidenceReduction}!`);
    }
  }

  // Track statistics
  updateStatistic('jobsCompleted');
  updateStatistic('totalMoneyEarned', earnings);
  trackJobCompletion(job.name); // Track individual job completion for favorite crime
  _jobsWithoutArrest++; // Track consecutive clean jobs for ghost achievement

  // Advanced Skills System Integration
  trackJobPlaystyle(job, true);
  updateFactionReputation(job, true);

  // Update mission progress
  updateMissionProgress('job_completed', 1);
  updateMissionProgress('money_earned', earnings);

  // Calculate chance of getting hurt based on job risk and player's power
  let hurtChance;
  let maxHealthLoss;
  // v1.11.0 Rebalance: Reputation gains per job risk tier (replaces old XP + rep split)
  if (job.risk === 'low') {
    hurtChance = Math.max(0, 1 - player.power * 0.01 - player.skillTree.combat.brawler * 0.5);
    maxHealthLoss = 5;
    gainExperience(1.0);
  } else if (job.risk === 'medium') {
    hurtChance = Math.max(0, 5 - player.power * 0.05 - player.skillTree.combat.brawler * 0.5);
    maxHealthLoss = 20;
    gainExperience(1.8);
  } else if (job.risk === 'high') {
    hurtChance = Math.max(0, 10 - player.power * 0.1 - player.skillTree.combat.brawler * 0.5);
    maxHealthLoss = 50;
    gainExperience(3.5);
  } else if (job.risk === 'very high') {
    hurtChance = Math.max(0, 15 - player.power * 0.12 - player.skillTree.combat.brawler * 0.5);
    maxHealthLoss = 60;
    gainExperience(5.0);
  } else if (job.risk === 'extreme') {
    hurtChance = Math.max(0, 20 - player.power * 0.15 - player.skillTree.combat.brawler * 0.5);
    maxHealthLoss = 75;
    gainExperience(8.0);
  } else if (job.risk === 'legendary') {
    hurtChance = Math.max(0, 25 - player.power * 0.18 - player.skillTree.combat.brawler * 0.5);
    maxHealthLoss = 90;
    gainExperience(12.0);
  }

  // Track reputation changes for campaign objectives
  updateMissionProgress('reputation_changed');

  // Toughness skill: -2% hurt chance per rank
  const toughnessLevel = player.skillTree.combat?.toughness || 0;
  if (toughnessLevel > 0) {
    hurtChance = Math.max(0, hurtChance * (1 - toughnessLevel * 0.02));
  }

  // Lucky Break skill: -5% hurt chance per rank (avoid negative events)
  const luckyBreakLevel = player.skillTree.luck?.lucky_break || 0;
  if (luckyBreakLevel > 0) {
    hurtChance = Math.max(0, hurtChance * (1 - luckyBreakLevel * 0.05));
  }

  // Morales Cartel reputation: Sicario training reduces hurt chance
  const moralesHurtMod = getStreetRepBonus('morales', 0, 0.05, 0.10, 0.15);
  if (moralesHurtMod !== 0) {
    hurtChance = Math.max(0, hurtChance * (1 - moralesHurtMod));
  }

  // Check if the player gets hurt
  if (Math.random() * 100 < hurtChance) {
    let healthLoss = Math.floor(Math.random() * maxHealthLoss) + 1;
    // Thick Skin perk: -25% health loss from jobs
    if (hasPlayerPerk('thick_skin')) {
      healthLoss = Math.max(1, Math.floor(healthLoss * 0.75));
    }
    // Resilience skill: -3% damage taken per rank
    const resilienceLevel = player.skillTree.endurance?.resilience || 0;
    if (resilienceLevel > 0) {
      healthLoss = Math.max(1, Math.floor(healthLoss * (1 - resilienceLevel * 0.03)));
    }
    // Resistance skill: -5% all damage taken per rank
    const resistanceLevel = player.skillTree.endurance?.resistance || 0;
    if (resistanceLevel > 0) {
      healthLoss = Math.max(1, Math.floor(healthLoss * (1 - resistanceLevel * 0.05)));
    }
    // Vitality skill: -2% damage taken per rank
    const vitalityLevel = player.skillTree.endurance?.vitality || 0;
    if (vitalityLevel > 0) {
      healthLoss = Math.max(1, Math.floor(healthLoss * (1 - vitalityLevel * 0.02)));
    }
    // Iron Warrior synergy (Combat+Endurance): -15% damage
    const ironWarriorBonus = getSynergyBonus('combatEndurance');
    if (ironWarriorBonus > 0) {
      healthLoss = Math.max(1, Math.floor(healthLoss * (1 - ironWarriorBonus)));
    }
    player.health -= healthLoss;
    flashHurtScreen();
    showBriefNotification(`${getRandomNarration('healthLoss')} You have ${player.health} health left.`, 'danger');
    logAction(`${getRandomNarration('healthLoss')} (-${healthLoss} health).`);
  }

  // Unstoppable skill (Second Wind): 3% chance per rank to recover 5 HP after a job
  const unstoppableLevel = player.skillTree.endurance?.unstoppable || 0;
  if (unstoppableLevel > 0 && player.health < 100 && Math.random() * 100 < unstoppableLevel * 3) {
    const windHeal = 5;
    player.health = Math.min(100, player.health + windHeal);
    logAction(`Second wind! Your endurance kicks in and you recover ${windHeal} HP.`);
    showBriefNotification(`Second Wind! +${windHeal} HP`, 'success');
  }

  // Lucky Devil perk: 10% chance for bonus cash loot on any job
  if (hasPlayerPerk('lucky_devil') && Math.random() < 0.10) {
    const bonusCash = Math.floor(earnings * 0.25); // 25% of base earnings as bonus
    player.money += bonusCash;
    logAction(` Lucky Devil! You found an extra $${bonusCash.toLocaleString()} while on the job!`);
    showBriefNotification(` Lucky bonus: +$${bonusCash.toLocaleString()}!`, 'success');
  }

  // Jackpot skill: +4% critical success chance per rank (double payout on crit)
  const jackpotLevel = player.skillTree.luck?.jackpot || 0;
  if (jackpotLevel > 0 && Math.random() * 100 < jackpotLevel * 4) {
    const critBonus = earnings;
    if (job.paysDirty) {
      player.dirtyMoney = (player.dirtyMoney || 0) + critBonus;
    } else {
      player.money += critBonus;
    }
    logAction(` JACKPOT! Critical success -- you scored an extra $${critBonus.toLocaleString()}!`);
    showBriefNotification(` JACKPOT! +$${critBonus.toLocaleString()}!`, 'success');
  }

  // Serendipity skill: +1% rare event chance per rank (bonus discovery)
  const serendipityLevel = player.skillTree.luck?.serendipity || 0;
  if (serendipityLevel > 0 && Math.random() * 100 < serendipityLevel) {
    const rareLoot = Math.floor(earnings * 0.5 + Math.random() * earnings * 0.5);
    player.money += rareLoot;
    logAction(` Serendipity! You stumble upon a hidden stash worth $${rareLoot.toLocaleString()}!`);
    showBriefNotification(` Rare find: +$${rareLoot.toLocaleString()}!`, 'success');
  }

  // Deduct ammo and gas if used
  if (job.requiredItems.includes('ammo')) player.ammo--;
  if (job.requiredItems.includes('gas')) player.gas--;

  // Check for first job achievement
  if (!achievements.find(a => a.id === 'first_job').unlocked) {
    unlockAchievement('first_job');
  }

  // Handle car damage if car was used
  let carCatastrophe = false;
  if (player.selectedCar !== null) {
    let damageAmount = Math.floor(Math.random() * 15) + 5; // 5-20% damage per use
    if (job.risk === 'high') damageAmount += 10;
    else if (job.risk === 'very high') damageAmount += 15;
    else if (job.risk === 'extreme') damageAmount += 20;
    else if (job.risk === 'legendary') damageAmount += 30;

    carCatastrophe = damageCar(player.selectedCar, damageAmount);
    if (!carCatastrophe) {
      logAction(`${getRandomNarration('carDamage')} (-${damageAmount}% condition).`);
    }
    player.selectedCar = null; // Reset selected car after use
  }

  if (!carCatastrophe) { // Only show success message if car didn't explode/break down
    const moneyType = job.paysDirty ? ' (dirty money -- must be laundered!)' : '';
    flashSuccessScreen();
    showBriefNotification(`You completed the job as a ${job.name} (${job.risk} risk) and earned $${earnings.toLocaleString()}${moneyType}!`, 'success');
    logAction(`${getFamilyNarration('jobSuccess')} (+$${earnings.toLocaleString()}${moneyType}).`);
  }

  // Share rewards with online crew members
  if (player.crewId && typeof sendMP === 'function') {
    sendMP({ type: 'crew_job_share', earnings: earnings, jobName: job.name, crewSize: crewSize });
  }

  degradeEquipment('job');
  updateUI();
  // Only refresh the job list instead of reloading the entire jobs screen to prevent flashing
  if (document.getElementById('jobs-screen').style.display === 'block') {
    refreshJobsList();
  }

  if (player.health <= 0) {
    showDeathScreen(`Killed on the job as a ${job.name}`);
  }
}

// Function to handle car theft
function handleCarTheft(job) {
  // Calculate jail chance with stealth skill reducing it
  let adjustedJailChance = Math.max(10, job.jailChance - (player.skillTree.stealth.shadow_step * 2));
  // Quick Hands perk: +10% car theft success (reduces jail chance)
  if (hasPlayerPerk('quick_hands')) {
    adjustedJailChance = Math.max(5, Math.floor(adjustedJailChance * 0.9));
  }
  // Heat-based arrest modifier
  const heatLevel = player.heat || 0;
  if (heatLevel <= 10) {
    adjustedJailChance = Math.floor(adjustedJailChance * 0.60);
  } else if (heatLevel <= 25) {
    adjustedJailChance = Math.floor(adjustedJailChance * 0.80);
  } else if (heatLevel <= 50) {
    // Normal police attention
  } else if (heatLevel <= 75) {
    adjustedJailChance = Math.floor(adjustedJailChance * 1.30) + 5;
  } else {
    adjustedJailChance = Math.floor(adjustedJailChance * 1.60) + 15;
  }
  adjustedJailChance = Math.max(5, Math.min(95, adjustedJailChance));
  let jailChance = Math.random() * 100;

  if (jailChance <= adjustedJailChance) {
    // Silk Voice skill: chance to talk your way out of arrest
    const silkVoiceCarTheft = player.skillTree?.charisma?.silk_voice || 0;
    if (silkVoiceCarTheft > 0 && Math.random() * 100 < silkVoiceCarTheft) {
      logAction('Smooth talking gets you off the hook -- the cops let you walk.');
      showBriefNotification('Silk Voice! You talked your way out of arrest.', 'warning');
    } else {
      sendToJail(job.heatGain, { crimeName: job.name, riskLevel: job.risk });
      return;
    }
  }

  // Check if player actually finds a car to steal (25% base chance)
  let findCarChance = 25 + (player.skillTree.luck.fortune * 2); // Luck skill helps find cars
  if (Math.random() * 100 > findCarChance) {
    showBriefNotification(`${getRandomNarration('carTheftFailure')} On cooldown.`, 'danger');
    logAction(`${getRandomNarration('carTheftFailure')} The streets can be unforgiving to those seeking easy rides.`);
    player.heat += 1; // Small heat increase for suspicious activity
    gainExperience(0.2);
    updateUI();
    // Only refresh the job list instead of reloading the entire jobs screen to prevent flashing
    if (document.getElementById('jobs-screen').style.display === 'block') {
      refreshJobsList();
    }
    return;
  }

  // Successfully found a car - determine which type based on rarity
  let totalRarity = stolenCarTypes.reduce((sum, car) => sum + car.rarity, 0);
  let randomValue = Math.random() * totalRarity;
  let currentSum = 0;
  let selectedCar = stolenCarTypes[0]; // Default fallback

  for (let car of stolenCarTypes) {
    currentSum += car.rarity;
    if (randomValue <= currentSum) {
      selectedCar = car;
      break;
    }
  }

  // Calculate initial damage percentage based on vehicle type
  // Most stolen vehicles are in terrible shape -- finding one in decent condition is very rare
  let damagePercentage = 0;

  // Broken vehicles: 95-100% damage (0-5% health left)
  if (selectedCar.name.toLowerCase().includes('broken')) {
    damagePercentage = Math.floor(Math.random() * 6) + 95; // 95-100% damage
  }
  // Rusted/Rusty vehicles: 65-96% damage (4-35% health left)
  else if (selectedCar.name.toLowerCase().includes('rust')) {
    damagePercentage = Math.floor(Math.random() * 32) + 65; // 65-96% damage
  }
  // All other vehicles: heavily weighted toward high damage
  else {
    // Roll a weighted chance -- most vehicles come badly damaged
    let conditionRoll = Math.random() * 100;
    if (conditionRoll < 45) {
      // 45% chance: severe damage 70-95%
      damagePercentage = Math.floor(Math.random() * 26) + 70;
    } else if (conditionRoll < 75) {
      // 30% chance: heavy damage 50-69%
      damagePercentage = Math.floor(Math.random() * 20) + 50;
    } else if (conditionRoll < 92) {
      // 17% chance: moderate damage 30-49%
      damagePercentage = Math.floor(Math.random() * 20) + 30;
    } else if (conditionRoll < 99) {
      // 7% chance: light damage 15-29%
      damagePercentage = Math.floor(Math.random() * 15) + 15;
    } else if (conditionRoll < 99.8) {
      // 0.8% chance: great condition 1-4%
      damagePercentage = Math.floor(Math.random() * 4) + 1;
    } else {
      // 0.2% chance: perfect mint condition
      damagePercentage = 0;
    }
  }

  let currentValue = Math.floor(selectedCar.baseValue * (1 - damagePercentage / 100));
  // Even totaled cars have scrap value (5-15% of base)
  const scrapMin = Math.floor(selectedCar.baseValue * 0.05);
  if (currentValue < scrapMin) currentValue = Math.floor(selectedCar.baseValue * (0.05 + Math.random() * 0.10));

  let stolenCar = {
    name: selectedCar.name,
    baseValue: selectedCar.baseValue,
    currentValue: currentValue,
    damagePercentage: damagePercentage,
    usageCount: 0
  };

  player.heat += job.heatGain;
  gainExperience(1.0);

  // Check if player gets hurt during theft
  if (Math.random() * 100 < 15) { // 15% chance of getting hurt
    let healthLoss = Math.floor(Math.random() * job.healthLoss) + 1;
    player.health -= healthLoss;
    flashHurtScreen();
    showCarTheftChoiceResult(stolenCar, true, healthLoss);
    logAction(`You grab the ${stolenCar.name} but the owner puts up a fight! Keys in hand, blood on your knuckles - it's yours now, but the price was pain (${damagePercentage}% damaged).`);
  } else {
    flashSuccessScreen();
    showCarTheftChoiceResult(stolenCar, false);
    logAction(`Like taking candy from a baby! You slip into the ${stolenCar.name} and drive off into the night. The engine purrs under your control (${damagePercentage}% damaged).`);
  }

  // Note: updateUI, achievement check, showJobs, and health check are now handled in handleStolenCarChoice
}

// Function to handle money laundering job -- converts dirty money to clean money
function handleLaunderMoneyJob(job, approachLabel) {
  // Cooldown was already set and dirty-money check done in startJob()

  // Calculate how much dirty money we can launder this run (based on job payout range + luck)
  let launderCapacity;
  if (Array.isArray(job.payout)) {
    launderCapacity = Math.floor(Math.random() * (job.payout[1] - job.payout[0] + 1)) + job.payout[0];
    launderCapacity += Math.floor(launderCapacity * (player.skillTree.luck.fortune * 0.02));
  } else {
    launderCapacity = job.payout;
  }

  // Approach modifies launder capacity BEFORE capping
  // Note: startJob() passes 'Loud' or 'Quiet' for high-risk jobs
  if (approachLabel === 'Loud') {
    launderCapacity = Math.floor(launderCapacity * 1.40); // Loud: +40% capacity (bulk laundering)
  } else if (approachLabel === 'Quiet') {
    launderCapacity = Math.floor(launderCapacity * 0.75); // Quiet/Stealth: -25% capacity (smaller batches, less risky)
  }

  // Can't launder more than you have
  const amountToLaunder = Math.min(launderCapacity, player.dirtyMoney);

  // Jail check -- stealth skills reduce the chance
  let stealthBonus = player.skillTree.stealth.shadow_step * 2;
  stealthBonus += player.skillTree.stealth.escape_artist * 3;
  stealthBonus += player.skillTree.stealth.infiltration * 2;
  let adjustedJailChance = Math.max(1, job.jailChance - stealthBonus);

  // Ghost Protocol synergy (Stealth+Intelligence): -20% arrest chance
  const ghostLaunderBonus = getSynergyBonus('stealthIntel');
  if (ghostLaunderBonus > 0) {
    adjustedJailChance = Math.max(1, Math.floor(adjustedJailChance * (1 - ghostLaunderBonus)));
  }

  // Heat-based risk: high heat makes laundering much more dangerous
  const currentHeat = player.heat || 0;
  adjustedJailChance += Math.floor(currentHeat * 0.15); // +15% jail chance at 100 heat

  // Approach modifies jail chance
  if (approachLabel === 'Quiet') {
    adjustedJailChance = Math.max(1, Math.floor(adjustedJailChance * 0.5)); // Quiet/Stealth: 50% less jail chance
  } else if (approachLabel === 'Loud') {
    adjustedJailChance = Math.floor(adjustedJailChance * 1.3); // Loud: 30% more jail chance
  }

  if (Math.random() * 100 <= adjustedJailChance) {
    // Silk Voice skill: chance to talk your way out of arrest
    const silkVoiceLaunder = player.skillTree?.charisma?.silk_voice || 0;
    if (silkVoiceLaunder > 0 && Math.random() * 100 < silkVoiceLaunder) {
      logAction('Smooth talking gets you off the hook -- the cops let you walk.');
      showBriefNotification('Silk Voice! You talked your way out of arrest.', 'warning');
    } else {
      // Caught! Lose the dirty money being laundered and go to jail
      const seized = Math.floor(amountToLaunder * (0.3 + Math.random() * 0.4)); // Feds seize 30-70%
      player.dirtyMoney = Math.max(0, player.dirtyMoney - seized);
      player.heat = Math.min(100, player.heat + 8);
      sendToJail(job.heatGain, { crimeName: job.name, riskLevel: job.risk });
      return;
    }
  }

  // Success! Convert dirty money to clean money with a conversion rate
  // Base rate 80-90%, improved by intelligence skills
  let conversionRate = 0.80 + (Math.random() * 0.10);

  // Intelligence skill improves conversion rate
  conversionRate += player.skillTree.intelligence.quick_study * 0.005; // +0.5% per level
  conversionRate += (player.skillTree.intelligence.forensics || 0) * 0.01; // +1% per forensics level

  // Approach bonus: each approach has distinct trade-offs
  if (approachLabel === 'Loud') {
    conversionRate -= 0.03; // Loud: -3% conversion (sloppy but fast)
    player.heat = Math.min(100, player.heat + 4); // +4 heat
    logAction('Going loud draws attention -- the feds notice the large cash movements.');
  } else if (approachLabel === 'Quiet') {
    conversionRate += 0.05; // Quiet: +5% conversion (careful, stealthy handling)
    // Quiet approach also reduces heat gain later
  }

  // Owning a Counterfeiting Operation improves conversion (mixing fake with real bills)
  if (player.businesses && player.businesses.some(b => b.id === 'counterfeiting')) {
    conversionRate += 0.03; // +3% if you own the Counterfeiting Operation
    logAction('Your Counterfeiting Operation helps mix the bills -- improved conversion rate.');
  }

  // Chen Triad smuggling network: buff.smugglingMultiplier boosts laundering conversion
  const smugBuff = getChosenFamilyBuff();
  if (smugBuff && smugBuff.smugglingMultiplier) {
    const smugBonus = (smugBuff.smugglingMultiplier - 1); // 1.30 -> 0.30
    conversionRate += smugBonus * 0.15; // +4.5% conversion rate from Chen network
    logAction('Chen Triad smuggling network improves your laundering channels.');
  }

  // Heat penalty: laundering under heat means paying more to intermediaries
  conversionRate -= currentHeat * 0.001; // -0.1% per heat (up to -10% at 100 heat)

  // Cap at 85%
  conversionRate = Math.min(0.85, conversionRate);

  const cleanAmount = Math.floor(amountToLaunder * conversionRate);
  const fee = amountToLaunder - cleanAmount;

  // Deduct dirty, add clean
  player.dirtyMoney -= amountToLaunder;
  player.money += cleanAmount;

  // Heat gain (reduced by perks/skills)
  let heatGain = job.heatGain;
  if (approachLabel === 'Loud') {
    heatGain = Math.ceil(heatGain * 1.3);
  }
  let intimidationReduction = player.skillTree.combat.intimidation * 0.1;
  heatGain = Math.max(1, Math.floor(heatGain * (1 - intimidationReduction)));
  if (hasUtilityItem('Police Scanner')) {
    heatGain = Math.max(1, Math.floor(heatGain * 0.8));
    logAction('Your Police Scanner intercepts radio chatter -- you dodge the heat.');
  }
  player.heat += heatGain;

  // Small heat gain even on success (modified by approach)
  let baseHeatGain = 1 + Math.floor(Math.random() * 3); // 1-3 heat
  if (approachLabel === 'Quiet') {
    baseHeatGain = Math.max(0, Math.floor(baseHeatGain * 0.3)); // Quiet: minimal heat
  }
  // Loud heat already added above
  player.heat = Math.min(100, player.heat + baseHeatGain);

  // Reputation based on risk level
  gainExperience(3.0);

  // Successful laundering boosts underground reputation
  if (player.streetReputation) {
    player.streetReputation.underground = Math.min(100, (player.streetReputation.underground || 0) + 1);
  }

  // Track statistics
  updateStatistic('jobsCompleted');
  updateStatistic('totalMoneyEarned', cleanAmount);
  trackJobCompletion(job.name);

  // Advanced Skills System Integration
  trackJobPlaystyle(job, true);
  updateFactionReputation(job, true);

  // Update mission progress
  updateMissionProgress('job_completed', 1);
  updateMissionProgress('money_earned', cleanAmount);

  // Forensics skill can reduce evidence trail
  if (player.skillTree.intelligence.forensics > 0) {
    let forensicsChance = player.skillTree.intelligence.forensics * 8;
    if (Math.random() * 100 < forensicsChance) {
      let evidenceReduction = Math.min(2, Math.floor(player.skillTree.intelligence.forensics / 3));
      player.heat = Math.max(0, player.heat - evidenceReduction);
      logAction(` Your forensics expertise helps you cover the paper trail, reducing heat by ${evidenceReduction}!`);
    }
  }

  const ratePercent = Math.round(conversionRate * 100);
  flashSuccessScreen();
  showBriefNotification(`Laundering successful! Cleaned $${cleanAmount.toLocaleString()} from $${amountToLaunder.toLocaleString()} dirty money (${ratePercent}% rate, $${fee.toLocaleString()} in fees).`, 'success');
  logAction(`The dirty bills flow through shell companies and emerge squeaky clean. $${amountToLaunder.toLocaleString()} dirty <-' $${cleanAmount.toLocaleString()} clean (${ratePercent}% rate). The laundering fee of $${fee.toLocaleString()} vanishes into the ether.`);

  // Refresh jobs UI if visible
  if (document.getElementById('jobs-screen').style.display === 'block') {
    refreshJobsList();
  }

  if (player.health <= 0) {
    showDeathScreen('Killed during a laundering operation gone wrong');
  }
}

