// Motor Pool moved into Stash screen as a tab
function showStolenCars() {
  showInventory('motorpool');
}

// Function to use a car for jobs
function useCar(index, purpose) {
  if (index >= 0 && index < player.stolenCars.length) {
    let car = player.stolenCars[index];

    if (car.damagePercentage >= 90) {
      showBriefNotification('This car is too damaged to use safely!', 'success');
      return;
    }

    if (purpose === 'job') {
      player.selectedCar = index;
      showBriefNotification(`Selected ${car.name} (${car.damagePercentage}% damaged) for your next job. It will provide bonuses but may take damage.`, 'success');
      logAction(`You pat the hood of your ${car.name} with a grin. This beauty will be your ride for the next job. Time to put it to work.`);
      showInventory('motorpool'); // Refresh the display
    }
  }
}

// Function to damage a car and handle consequences
function damageCar(carIndex, damageAmount) {
  if (carIndex === null || carIndex >= player.stolenCars.length) return false;

  let car = player.stolenCars[carIndex];
  car.damagePercentage += damageAmount;
  car.usageCount++;

  // Recalculate current value (minimum scrap value of 5-15%)
  car.currentValue = Math.floor(car.baseValue * (1 - car.damagePercentage / 100));
  const scrapFloor = Math.floor(car.baseValue * 0.05);
  if (car.currentValue < scrapFloor) car.currentValue = Math.floor(car.baseValue * (0.05 + Math.random() * 0.10));

  if (car.damagePercentage >= 100) {
    // Car is completely destroyed
    let catastrophe = Math.random();

    if (catastrophe < 0.4) { // 40% chance - explosion
      player.health -= 30;
      showBriefNotification(`Your car exploded! ${getRandomNarration('healthLoss')} The vehicle is destroyed!`, true, 'success');
      logAction(`${getRandomNarration('healthLoss')} Sometimes taking risks with damaged equipment backfires spectacularly.`);
      logAction('BOOM! The car erupts in flames! You dive clear as metal and glass rain down around you. The explosion echoes through the streets (-30 health).');
      flashHurtScreen();
    } else if (catastrophe < 0.7) { // 30% chance - breakdown and caught
      sendToJail(5, { crimeName: 'Vehicle Breakdown', riskLevel: 'medium' });
      showBriefNotification('Your car broke down and you were caught by police!', 'success');
      logAction("The engine dies with a pathetic wheeze. Steam rises from the hood as cop cars surround you. Should've maintained your ride better!");
    } else { // 30% chance - just destroyed
      showBriefNotification('Your car finally gave out and is completely destroyed.', 'success');
      logAction('The car finally gives up the ghost. Metal grinds against metal as it dies. You walk away from the smoking wreck - time to find new wheels.');
    }

    // Remove the destroyed car
    player.stolenCars.splice(carIndex, 1);
    player.selectedCar = null;

    return true; // Indicates catastrophic failure
  }

  return false; // Normal damage
}

// Function to flash the screen red when the player gets hurt
function flashHurtScreen() {
  const hurtFlash = document.getElementById('hurt-flash');
  hurtFlash.style.display = 'block';
  setTimeout(() => {
    hurtFlash.style.display = 'none';
  }, 200);
}

function flashSuccessScreen() {
  const flash = document.getElementById('success-flash');
  if (!flash) return;
  flash.style.display = 'block';
  // Reset animation by forcing reflow
  flash.style.animation = 'none';
  flash.offsetHeight; // trigger reflow
  flash.style.animation = '';
  setTimeout(() => {
    flash.style.display = 'none';
  }, 500);
}

// Function to send player to jail
function sendToJail(heatLoss, crimeContext) {
  stopJailTimer();

  player.inJail = true;
  _jobsWithoutArrest = 0; // Reset consecutive clean jobs on arrest

  // Jail time scales with heat but caps at 90 seconds. Escape skill reduces time.
  const escapeReduction = (player.skillTree.stealth.escape_artist || 0) * 2; // -2s per escape level
  const baseJailTime = Math.min(90, 15 + Math.floor(player.heat * 0.8));
  let calculatedJailTime = Math.max(10, baseJailTime - escapeReduction);

  // Corruption: Judge sentence reduction
  const corruptSentenceReduction = getCorruptionBenefit('sentenceReduction');
  if (corruptSentenceReduction > 0) {
    const reduced = Math.floor(calculatedJailTime * corruptSentenceReduction);
    calculatedJailTime = Math.max(5, calculatedJailTime - reduced);
    logAction(`Your judge on the payroll pulls strings -- sentence reduced by ${reduced}s.`);
  }

  // Iron Will perk: -25% jail time
  if (hasPlayerPerk('iron_will')) {
    const reduced = Math.floor(calculatedJailTime * 0.25);
    calculatedJailTime = Math.max(5, calculatedJailTime - reduced);
    logAction(`Iron Will kicks in -- your jail sentence is shortened by ${reduced}s.`);
  }

  // Heat-based sentence modifier: low heat = shorter, high heat = longer
  const heatLevelForJail = player.heat || 0;
  if (heatLevelForJail < 10) {
    const change = Math.floor(calculatedJailTime * 0.25);
    calculatedJailTime = Math.max(5, calculatedJailTime - change);
    logAction(`Low heat keeps you under the radar -- sentence reduced by ${change}s.`);
  } else if (heatLevelForJail < 20) {
    const change = Math.floor(calculatedJailTime * 0.10);
    calculatedJailTime = Math.max(5, calculatedJailTime - change);
    logAction(`Moderate profile keeps your sentence manageable (-${change}s).`);
  } else if (heatLevelForJail > 80) {
    const change = Math.floor(calculatedJailTime * 0.30);
    calculatedJailTime += change;
    logAction(`You're public enemy #1 -- the judge throws the book at you (+${change}s).`);
  } else if (heatLevelForJail > 60) {
    const change = Math.floor(calculatedJailTime * 0.15);
    calculatedJailTime += change;
    logAction(`High heat draws extra scrutiny -- sentence increased by ${change}s.`);
  }

  // Utility item: Lockpick Set reduces jail time by 5 seconds
  if (hasUtilityItem('Lockpick Set')) {
    calculatedJailTime = Math.max(5, calculatedJailTime - 5);
    logAction(' Your Lockpick Set makes short work of the cell lock -- shorter sentence!');
  }

  player.jailTime = calculatedJailTime;

  if (window.EventBus) {
    try { EventBus.emit('jailStatusChanged', { inJail: true, jailTime: player.jailTime }); } catch(e) { console.warn('EventBus emit error:', e); }
  }

  player.heat -= heatLoss; // Lose heat when in jail
  player.heat = Math.max(0, player.heat); // Ensure heat doesn't go negative

  player.reputation = Math.max(0, player.reputation - 1); // Lose 1 reputation point, but not below 0
  player.breakoutAttempts = 3; // Reset breakout attempts

  // Update statistics
  updateStatistic('timesArrested', 1);

  generateJailPrisoners(); // Generate random prisoners in jail
  updateUI(); // Update UI
  updateJailUI(); // Ensure jail-specific UI elements are synced
  updateJailTimer(); // Start the jail timer

  // Generate and show jail newspaper headline
  const jailNewspaperData = generateJailNewspaperData(crimeContext);
  lastJailNewspaperData = jailNewspaperData;
  logAction(`<span class="newspaper-chat-link" onclick="showLastJailNewspaper()">Read the Headlines: ${player.name} ARRESTED!</span>`, 'chat');

  // Broadcast jail newspaper to world chat via multiplayer (if connected)
  if (typeof broadcastJailNewspaper === 'function') {
    broadcastJailNewspaper(jailNewspaperData);
  }

  // Sync jail status to server so other players can see us in the jail list
  if (typeof syncJailStatus === 'function') syncJailStatus(true, player.jailTime);

  // Show the jail screen
  showJailScreen();
}

// Bribe guard to get released early
function bribeGuard() {
  let bribeCost = Math.floor(1000 + (player.reputation || 0) * 15 + player.heat * 200);
  // Silver Tongue perk: -10% bribe cost
  if (hasPlayerPerk('silver_tongue')) {
    bribeCost = Math.floor(bribeCost * 0.90);
  }

  if (player.money < bribeCost) {
    showBriefNotification(`You need $${bribeCost.toLocaleString()} to bribe the guard. You only have $${Math.floor(player.money).toLocaleString()}.`, 'warning');
    return;
  }

  player.money -= bribeCost;
  player.inJail = false;
  player.jailTime = 0;
  player.breakoutAttempts = 3;


  // Bribing guards reduces heat slightly
  player.heat = Math.max(0, (player.heat || 0) - 3);

  stopJailTimer();
  window._jailReleaseGrace = Date.now();

  if (window.EventBus) {
    try { EventBus.emit('jailStatusChanged', { inJail: false, jailTime: 0 }); } catch(e) { console.warn('EventBus emit error:', e); }
  }

  // Sync release to server
  if (typeof syncJailStatus === 'function') syncJailStatus(false, 0);

  updateUI();
  showBriefNotification(`You slipped the guard $${bribeCost.toLocaleString()} and walked out the back door.`, 'success');
  logAction(`Bribed a guard $${bribeCost.toLocaleString()} to get out of jail early.`);
  goBackToMainMenu();
}

// Jail breakout attempt
function attemptBreakout() {
  if (player.breakoutAttempts <= 0) {
    showBriefNotification('You have no breakout attempts left!', 'danger');
    return;
  }

  player.breakoutAttempts--;
  player.heat++; // Increase heat with each breakout attempt

  // Stealth skill improves breakout chance
  let adjustedBreakoutChance = player.breakoutChance + (player.skillTree.stealth.escape_artist * 3);
  // Iron Will perk: +10% breakout success
  if (hasPlayerPerk('iron_will')) adjustedBreakoutChance += 10;
  // Synergy: Survivor (endurance + luck) bonus
  adjustedBreakoutChance += Math.floor(getSynergyBonus('enduranceLuck') * 100);
  adjustedBreakoutChance = Math.min(95, adjustedBreakoutChance);
  let success = Math.random() * 100 < adjustedBreakoutChance;

  if (success) {
    player.inJail = false;
    player.jailTime = 0;
    player.breakoutAttempts = 3; // Reset breakout attempts

    stopJailTimer();
    // Grace period: prevent multiplayer sync from re-jailing us before the
    // server has processed our release (fixes race condition with world_update).
    window._jailReleaseGrace = Date.now();

    if (window.EventBus) {
      try { EventBus.emit('jailStatusChanged', { inJail: false, jailTime: 0 }); } catch(e) { console.warn('EventBus emit error:', e); }
    }

    // Sync release to server
    if (typeof syncJailStatus === 'function') syncJailStatus(false, 0);

    // Update statistics
    updateStatistic('timesEscaped', 1);

    updateUI();
    showBriefNotification(`${getRandomNarration('jailBreakouts')}`, 'success');
    logAction(getRandomNarration('jailBreakouts'));

    // Check for jail break achievement
    if (!achievements.find(a => a.id === 'jail_break').unlocked) {
      unlockAchievement('jail_break');
    }

    goBackToMainMenu();
  } else {
    player.jailTime += 10; // Add 10 seconds to jail time on failed breakout attempt

    // Sync extended time to server so it doesn't overwrite with the old shorter value
    if (typeof syncJailStatus === 'function') syncJailStatus(true, player.jailTime);

    updateUI();
    showBriefNotification(`${getRandomNarration('jailBreakoutFailure')} Additional time has been added to your sentence.`, 'danger');
    logAction("The guard's flashlight catches you red-handed! Alarms blare as they drag you back to your cell. Some lessons are learned the hard way.");

    showJailScreen(); // Update the breakout button text
  }
}

// ---
// UNIFIED RPG SKILL TREE SYSTEM
// ---

// Synergy definitions: when 2 trees both have deep investment, grant cross-tree bonuses
const SKILL_SYNERGIES = [
  { trees: ['combat', 'stealth'], name: 'Silent Killer', desc: '+12% bounty board success chance', minPts: 10, bonus: { type: 'combatStealth', value: 0.12 } },
  { trees: ['combat', 'endurance'], name: 'Iron Warrior', desc: '+15% damage resistance from jobs and bounties', minPts: 10, bonus: { type: 'combatEndurance', value: 0.15 } },
  { trees: ['stealth', 'intelligence'], name: 'Ghost Protocol', desc: '-20% arrest chance on all jobs', minPts: 10, bonus: { type: 'stealthIntel', value: 0.20 } },
  { trees: ['charisma', 'intelligence'], name: 'Mastermind', desc: '+15% job payout bonus', minPts: 10, bonus: { type: 'charismaIntel', value: 0.15 } },
  { trees: ['luck', 'charisma'], name: 'Silver Tongue', desc: '+10% casino winnings and store discounts', minPts: 10, bonus: { type: 'luckCharisma', value: 0.10 } },
  { trees: ['endurance', 'luck'], name: 'Survivor', desc: '+18% jail breakout chance', minPts: 10, bonus: { type: 'enduranceLuck', value: 0.18 } },
];

// Calculate which synergies are active
function getActiveSynergies() {
  return SKILL_SYNERGIES.filter(syn => {
    return syn.trees.every(t => getTreePointsSpent(t) >= syn.minPts);
  });
}

// Get a specific synergy bonus value (returns 0 if not active)
function getSynergyBonus(bonusType) {
  const active = getActiveSynergies();
  const match = active.find(s => s.bonus.type === bonusType);
  return match ? match.bonus.value : 0;
}
window.getSynergyBonus = getSynergyBonus;

// ── Gym-Style Skill Training Config ──
// Training costs scale with tier and current rank.
const SKILL_TRAINING_CONFIG = {
  1: { baseMoney: 1500, moneyPerRank: 1000, baseTime: 60, timePerRank: 15 },
  2: { baseMoney: 8000, moneyPerRank: 4000, baseTime: 90, timePerRank: 30 },
  3: { baseMoney: 25000, moneyPerRank: 12000, baseTime: 150, timePerRank: 45 }
};

function getTrainingCost(treeName, nodeId) {
  const treeDef = SKILL_TREE_DEFS[treeName];
  if (!treeDef) return null;
  const nodeDef = treeDef.nodes[nodeId];
  if (!nodeDef) return null;
  const rank = player.skillTree[treeName][nodeId] || 0;
  const cfg = SKILL_TRAINING_CONFIG[nodeDef.tier];
  if (!cfg) return null;
  return {
    money: cfg.baseMoney + rank * cfg.moneyPerRank,
    time: cfg.baseTime + rank * cfg.timePerRank
  };
}

function formatTrainingTime(seconds) {
  if (seconds >= 60) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return s > 0 ? `${m}m ${s}s` : `${m}m`;
  }
  return `${seconds}s`;
}

// Currently selected tree in the skill UI
let _activeSkillTree = 'stealth';

// Compute current & next-rank stat text from a skill's effect string
function getSkillStatLine(effect, rank, maxRank) {
  // Split compound effects like "-2s jail time, +3% breakout per rank"
  const parts = effect.split(',').map(s => s.trim());
  const currentParts = [];
  const nextParts = [];
  for (const part of parts) {
    // Match patterns like "+5%", "-2s", "8%" at the start or after a space
    const m = part.match(/([+-]?)(\d+(?:\.\d+)?)\s*(%|s)/);
    if (!m) continue;
    const sign = m[1] || '+';
    const perRank = parseFloat(m[2]);
    const unit = m[3];
    const curVal = perRank * rank;
    const nxtVal = rank < maxRank ? perRank * (rank + 1) : curVal;
    // Extract the label: strip the leading number+unit and "per rank" portion
    const stripped = part.replace(/[+-]?\d+(?:\.\d+)?\s*(%|s)\s*/, '').replace(/\s*per rank\s*/i, ' ').trim();
    currentParts.push(`${sign}${curVal}${unit} ${stripped}`);
    if (rank < maxRank) {
      nextParts.push(`${sign}${nxtVal}${unit} ${stripped}`);
    }
  }
  if (currentParts.length === 0) return '';
  const now = currentParts.join(', ');
  const next = nextParts.length > 0 ? nextParts.join(', ') : null;
  if (rank === 0 && next) return `<p class="rpg-node-stats"><span style="color:#8a7a5a;">Now: none</span> <span style="color:#8a9a6a;">Next: ${next}</span></p>`;
  if (!next || rank >= maxRank) return `<p class="rpg-node-stats"><span style="color:#c0a062;">Now: ${now}</span> <span style="color:#d4af37;">MAXED</span></p>`;
  return `<p class="rpg-node-stats"><span style="color:#c0a062;">Now: ${now}</span> <span style="color:#8a9a6a;">Next: ${next}</span></p>`;
}

function showSkills() {
  if (player.inJail) {
    showBriefNotification("You can't access skills while you're in jail!", 'danger');
    return;
  }
  hideAllScreens();
  const screen = document.getElementById('skills-screen');
  screen.style.display = 'block';
  screen.innerHTML = '<div id="skills-content"></div>';
  renderSkillTreeUI();
}

function renderSkillTreeUI() {
  const totalPts = Object.values(player.skillTree).reduce((s, nodes) => s + Object.values(nodes).reduce((a, b) => a + b, 0), 0);
  const isTraining = player.activeTraining != null;

  // Training status banner
  let trainingBannerHTML = '';
  if (isTraining) {
    const t = player.activeTraining;
    const elapsed = Date.now() - t.startTime;
    const remaining = Math.max(0, t.duration - elapsed);
    const remainSec = Math.ceil(remaining / 1000);
    const pct = Math.min(100, (elapsed / t.duration) * 100);
    const nodeDef = SKILL_TREE_DEFS[t.tree]?.nodes[t.node];
    trainingBannerHTML = `
      <div class="skill-training-banner">
        <div class="skill-training-banner-info">
          Currently Training: <strong>${nodeDef?.name || t.node}</strong>
          <span class="skill-training-countdown" id="training-countdown">${formatTrainingTime(remainSec)}</span>
        </div>
        <div class="skill-training-progress">
          <div class="skill-training-progress-fill" id="training-progress-fill" style="width:${pct}%"></div>
        </div>
        <button onclick="cancelSkillTraining()" class="skill-training-cancel-btn">Cancel Training (50% refund)</button>
      </div>`;
  }

  // Build tree selector tabs
  const treeTabs = Object.entries(SKILL_TREE_DEFS).map(([id, def]) => {
    const pts = getTreePointsSpent(id);
    const active = id === _activeSkillTree;
    return `<button onclick="selectSkillTree('${id}')" class="rpg-tree-tab ${active ? 'rpg-tree-tab-active' : ''}" style="--tab-color:${def.color}">
      <span class="rpg-tree-tab-icon">${def.icon}</span>
      <span class="rpg-tree-tab-name">${def.name}</span>
      <span class="rpg-tree-tab-pts">${pts} pts</span>
    </button>`;
  }).join('');

  // Build the active tree
  const treeDef = SKILL_TREE_DEFS[_activeSkillTree];
  const treeData = player.skillTree[_activeSkillTree];
  const ptsInTree = getTreePointsSpent(_activeSkillTree);

  // Separate nodes by tier
  const tiers = [1, 2, 3];
  const tierLabels = ['Foundation', 'Specialization', 'Mastery'];
  const tierReqs = [0, 5, 20];

  let treeNodesHTML = '';
  for (let ti = 0; ti < tiers.length; ti++) {
    const tier = tiers[ti];
    const tierNodes = Object.entries(treeDef.nodes).filter(([, n]) => n.tier === tier);
    const tierUnlocked = ptsInTree >= tierReqs[ti];

    treeNodesHTML += `
      <div class="rpg-tier-section">
        <div class="rpg-tier-header">
          <span class="rpg-tier-label">${tierLabels[ti]} -- Tier ${tier}</span>
          <span class="rpg-tier-req ${tierUnlocked ? 'rpg-tier-unlocked' : ''}">${tierReqs[ti] > 0 ? (tierUnlocked ? ' Unlocked' : `Requires ${tierReqs[ti]} pts in tree (${ptsInTree}/${tierReqs[ti]})`) : 'Always Available'}</span>
        </div>
        ${tier > 1 ? '<div class="rpg-tier-connector"><div class="rpg-connector-line"></div></div>' : ''}
        <div class="rpg-tier-nodes">
    `;

    for (const [nodeId, nodeDef] of tierNodes) {
      const rank = treeData[nodeId] || 0;
      const maxRank = nodeDef.maxRank;
      const prereqsMet = canUnlockNode(_activeSkillTree, nodeId);
      const isMaxed = rank >= maxRank;
      const meetsPrereqs = nodeDef.prereqs.every(req => (treeData[req.node] || 0) >= req.rank);
      const isLocked = !tierUnlocked || !meetsPrereqs;
      const pctFill = Math.round((rank / maxRank) * 100);

      // Training state for this node
      const isThisNodeTraining = isTraining && player.activeTraining.tree === _activeSkillTree && player.activeTraining.node === nodeId;
      const cost = getTrainingCost(_activeSkillTree, nodeId);
      const canAfford = cost && player.money >= cost.money;
      const canTrain = prereqsMet && !isTraining && canAfford;

      // Prereq display
      let prereqText = '';
      if (nodeDef.prereqs.length > 0) {
        prereqText = nodeDef.prereqs.map(req => {
          const reqDef = treeDef.nodes[req.node];
          const reqMet = (treeData[req.node] || 0) >= req.rank;
          return `<span style="color:${reqMet ? '#8a9a6a' : '#8b3a3a'}">${reqMet ? '' : ''} ${reqDef.name} Rank ${req.rank}</span>`;
        }).join(' ');
      }

      // Build button
      let buttonHTML = '';
      if (isMaxed) {
        buttonHTML = '<button class="rpg-node-btn" disabled>MASTERED</button>';
      } else if (isLocked) {
        buttonHTML = '<button class="rpg-node-btn" disabled>Locked</button>';
      } else if (isThisNodeTraining) {
        const t = player.activeTraining;
        const elapsed = Date.now() - t.startTime;
        const remaining = Math.max(0, t.duration - elapsed);
        const remainSec = Math.ceil(remaining / 1000);
        const trainPct = Math.min(100, (elapsed / t.duration) * 100);
        buttonHTML = `
          <div class="rpg-node-training-timer">
            <div class="rpg-node-training-bar"><div class="rpg-node-training-bar-fill" style="width:${trainPct}%"></div></div>
            <span class="rpg-node-training-time" id="node-train-time-${nodeId}">${formatTrainingTime(remainSec)}</span>
          </div>
          <button onclick="cancelSkillTraining()" class="rpg-node-btn rpg-node-btn-cancel">Cancel</button>`;
      } else if (isTraining) {
        buttonHTML = '<button class="rpg-node-btn" disabled>Busy Training</button>';
      } else if (!prereqsMet) {
        buttonHTML = '<button class="rpg-node-btn" disabled>Locked</button>';
      } else {
        const costLabel = `${formatTrainingTime(cost.time)} | $${cost.money.toLocaleString()}`;
        buttonHTML = `<button onclick="startSkillTraining('${_activeSkillTree}', '${nodeId}')" class="rpg-node-btn ${canTrain ? 'rpg-node-btn-active' : ''}" ${!canTrain ? 'disabled' : ''}>
          Train (${costLabel})
        </button>`;
        if (!canAfford && cost) {
          const reasons = [];
          if (player.money < cost.money) reasons.push(`Need $${cost.money.toLocaleString()}`);
          buttonHTML += `<small class="rpg-node-cost-warn">${reasons.join(' | ')}</small>`;
        }
      }

      treeNodesHTML += `
        <div class="rpg-node ${isMaxed ? 'rpg-node-maxed' : ''} ${isLocked ? 'rpg-node-locked' : ''} ${canTrain ? 'rpg-node-available' : ''} ${isThisNodeTraining ? 'rpg-node-training' : ''}" style="--node-color:${treeDef.color}">
          <div class="rpg-node-header">
            <span class="rpg-node-icon">${nodeDef.icon}</span>
            <div class="rpg-node-title">
              <span class="rpg-node-name">${nodeDef.name}</span>
              <span class="rpg-node-rank">${rank} / ${maxRank}</span>
            </div>
          </div>
          <div class="rpg-node-bar">
            <div class="rpg-node-bar-fill" style="width:${pctFill}%;background:${isMaxed ? '#d4af37' : treeDef.color}"></div>
          </div>
          <p class="rpg-node-desc">${nodeDef.desc}</p>
          <p class="rpg-node-effect">${nodeDef.effect}</p>
          ${getSkillStatLine(nodeDef.effect, rank, maxRank)}
          ${prereqText ? `<div class="rpg-node-prereqs">Requires: ${prereqText}</div>` : ''}
          ${buttonHTML}
        </div>
      `;
    }
    treeNodesHTML += '</div></div>';
  }

  document.getElementById('skills-content').innerHTML = `
    <div class="rpg-skill-container">
      <div class="rpg-skill-header">
        <h2 class="rpg-skill-title">Training Gym</h2>
        <div class="rpg-skill-summary">Total trained: ${totalPts} ranks across all trees</div>
      </div>

      ${trainingBannerHTML}

      <div class="rpg-tree-tabs">${treeTabs}</div>

      <div class="rpg-tree-panel" style="--tree-color:${treeDef.color}">
        <div class="rpg-tree-title-bar">
          <span class="rpg-tree-title-icon">${treeDef.icon}</span>
          <div>
            <h3 class="rpg-tree-title">${treeDef.name}</h3>
            <p class="rpg-tree-desc">${treeDef.desc}</p>
          </div>
          <span class="rpg-tree-invested">${ptsInTree} pts invested</span>
        </div>
        ${treeNodesHTML}
      </div>

      <div class="rpg-synergy-panel" style="margin-top:20px;padding:15px;background:rgba(20,18,10,0.6);border-radius:10px;border:1px solid #3a3520;">
        <h3 style="color:#d4af37;margin:0 0 10px;">Cross-Tree Synergies</h3>
        <p style="color:#8a7a5a;font-size:0.85em;margin:0 0 10px;">Invest 10+ points in two connected trees to unlock powerful synergy bonuses.</p>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;">
          ${SKILL_SYNERGIES.map(syn => {
            const pts = syn.trees.map(t => getTreePointsSpent(t));
            const isActive = pts.every(p => p >= syn.minPts);
            const progress = pts.map((p, i) => {
              const tDef = SKILL_TREE_DEFS[syn.trees[i]];
              return `${tDef.icon} ${tDef.name}: ${p}/${syn.minPts}`;
            }).join(' + ');
            return `<div style="padding:10px;border-radius:6px;border:1px solid ${isActive ? '#d4af37' : '#3a3520'};background:${isActive ? 'rgba(212,175,55,0.1)' : 'rgba(20,18,10,0.4)'};">
              <strong style="color:${isActive ? '#d4af37' : '#8a7a5a'};">${syn.name}</strong>
              <p style="color:${isActive ? '#f5e6c8' : '#666'};font-size:0.85em;margin:4px 0;">${syn.desc}</p>
              <small style="color:${isActive ? '#8a9a6a' : '#555'};">${isActive ? 'ACTIVE' : progress}</small>
            </div>`;
          }).join('')}
        </div>
      </div>

      <div style="text-align:center;margin-top:20px;">
        <button class="nav-btn-back" onclick="respecSkillTree()" style="background:#8b3a3a;color:#f5e6c8;border:1px solid #c0a062;padding:10px 20px;border-radius:6px;cursor:pointer;margin-right:8px;font-weight:bold;">Reset Skills ($${(10000 * Math.pow(2, player.respecCount || 0)).toLocaleString()})</button>
        <button class="nav-btn-back" onclick="goBackToMainMenu()"><- Back to SafeHouse</button>
      </div>
    </div>
  `;
}

function selectSkillTree(treeId) {
  _activeSkillTree = treeId;
  renderSkillTreeUI();
}

function startSkillTraining(treeName, nodeId) {
  if (player.activeTraining) {
    showBriefNotification('Already training a skill! Finish or cancel first.', 'warning');
    return;
  }
  if (!canUnlockNode(treeName, nodeId)) {
    const nodeDef = SKILL_TREE_DEFS[treeName]?.nodes[nodeId];
    if (!nodeDef) return;
    const rank = player.skillTree[treeName][nodeId] || 0;
    if (rank >= nodeDef.maxRank) {
      showBriefNotification(`${nodeDef.name} is already maxed out!`, 'warning');
    } else {
      showBriefNotification(`Prerequisites not met for ${nodeDef.name}.`, 'warning');
    }
    return;
  }

  const cost = getTrainingCost(treeName, nodeId);
  if (!cost) return;

  if (player.money < cost.money) {
    showBriefNotification(`Not enough money! Need $${cost.money.toLocaleString()}.`, 'danger');
    return;
  }

  // Deduct costs upfront
  player.money -= cost.money;

  // Start training timer
  player.activeTraining = {
    tree: treeName,
    node: nodeId,
    startTime: Date.now(),
    duration: cost.time * 1000,
    moneyCost: cost.money
  };

  const nodeDef = SKILL_TREE_DEFS[treeName].nodes[nodeId];
  logAction(`You begin training ${nodeDef.name}. This will take ${formatTrainingTime(cost.time)}.`);
  showBriefNotification(`Training ${nodeDef.name}... ${formatTrainingTime(cost.time)}`, 'info');

  updateUI();
  _refreshSkillTreeUI();
}

function cancelSkillTraining() {
  if (!player.activeTraining) return;

  const t = player.activeTraining;
  const nodeDef = SKILL_TREE_DEFS[t.tree]?.nodes[t.node];
  const refund = Math.floor(t.moneyCost * 0.5);
  player.money += refund;
  player.activeTraining = null;

  showBriefNotification(`Training cancelled. $${refund.toLocaleString()} refunded.`, 'warning');
  logAction(`You stopped training ${nodeDef?.name || t.node}. Half of the training fee was refunded.`);

  updateUI();
  _refreshSkillTreeUI();
}

function completeSkillTraining() {
  if (!player.activeTraining) return;

  const t = player.activeTraining;
  player.skillTree[t.tree][t.node]++;
  const nodeDef = SKILL_TREE_DEFS[t.tree].nodes[t.node];
  const newRank = player.skillTree[t.tree][t.node];
  player.activeTraining = null;

  if (newRank >= nodeDef.maxRank) {
    showBriefNotification(`MASTERED: ${nodeDef.name}! Maximum rank reached.`, 'success');
    logAction(`${nodeDef.name} MASTERED! You've reached rank ${newRank} -- the pinnacle of this discipline.`);
  } else {
    showBriefNotification(`${nodeDef.name} trained to rank ${newRank}!`, 'success');
    logAction(`Training complete! ${nodeDef.name} improved to rank ${newRank}. ${nodeDef.effect}`);
  }

  player.playstyleStats.skillTreeUpgrades = (player.playstyleStats.skillTreeUpgrades || 0) + 1;

  updateUI();
  _refreshSkillTreeUI();
}

// Called every second to update training countdown and check completion
function tickSkillTraining() {
  if (!player.activeTraining) return;

  const t = player.activeTraining;
  const elapsed = Date.now() - t.startTime;

  if (elapsed >= t.duration) {
    completeSkillTraining();
    return;
  }

  // Update countdown display without full re-render
  const remaining = Math.max(0, t.duration - elapsed);
  const remainSec = Math.ceil(remaining / 1000);
  const pct = Math.min(100, (elapsed / t.duration) * 100);

  const countdownEl = document.getElementById('training-countdown');
  if (countdownEl) countdownEl.textContent = formatTrainingTime(remainSec);

  const progressEl = document.getElementById('training-progress-fill');
  if (progressEl) progressEl.style.width = pct + '%';

  // Update node-level timer if visible
  const nodeTimeEl = document.getElementById(`node-train-time-${t.node}`);
  if (nodeTimeEl) nodeTimeEl.textContent = formatTrainingTime(remainSec);
}

// Helper: re-render skill tree UI
function _refreshSkillTreeUI() {
  renderSkillTreeUI();
}

// Start the 1-second skill training timer
let _skillTrainingInterval = null;
function startSkillTrainingTimer() {
  if (_skillTrainingInterval) clearInterval(_skillTrainingInterval);
  _skillTrainingInterval = setInterval(tickSkillTraining, 1000);
}

// Gang rescue attempt -- send your crew to break you out of jail
async function attemptGangRescue() {
  if (!player.inJail) return;
  const availableMembers = player.gang.gangMembers.filter(m => !m.arrested && !m.onOperation);
  if (availableMembers.length === 0) {
    showBriefNotification('No available crew members to send!', 'danger');
    return;
  }

  const rescueChance = Math.min(90, 20 + availableMembers.length * 10);

  if (!await ui.confirm(`<strong>Gang Rescue Operation</strong><br><br>Your crew of ${availableMembers.length} will attempt a jailbreak.<br>Success chance: <strong>${rescueChance}%</strong><br><br>If the rescue fails, some crew members may get arrested.<br><br>Proceed?`)) {
    return;
  }
  const success = Math.random() * 100 < rescueChance;

  if (success) {
    player.inJail = false;
    player.jailTime = 0;
    player.breakoutAttempts = 3;
    stopJailTimer();
    window._jailReleaseGrace = Date.now();

    if (window.EventBus) {
      try { EventBus.emit('jailStatusChanged', { inJail: false, jailTime: 0 }); } catch(e) { console.warn('EventBus emit error:', e); }
    }
    if (typeof syncJailStatus === 'function') syncJailStatus(false, 0);

    // One member gets a small injury/heat
    const rescuer = availableMembers[Math.floor(Math.random() * availableMembers.length)];
    rescuer.xp = (rescuer.xp || 0) + 30;

    updateUI();
    showBriefNotification(`Your crew pulled off the rescue! ${rescuer.name} led the charge.`, 'success');
    logAction(`A black van screeches up to the prison yard wall. ${rescuer.name} throws a rope over the top. Before the guards react, you're gone. Another day, another miracle.`);
    goBackToMainMenu();
  } else {
    // Failed rescue -- 1-2 members get arrested
    const arrestCount = Math.min(availableMembers.length, Math.floor(Math.random() * 2) + 1);
    const arrested = [];
    const shuffled = [...availableMembers].sort(() => Math.random() - 0.5);
    for (let i = 0; i < arrestCount && i < shuffled.length; i++) {
      const unlucky = shuffled[i];
      unlucky.arrested = true;
      unlucky.arrestTime = Date.now() + (Math.random() * 36 + 12) * 60 * 60 * 1000;
      arrested.push(unlucky.name);
    }

    player.jailTime += 15; // Extra time for the attempt
    if (typeof syncJailStatus === 'function') syncJailStatus(true, player.jailTime);

    showBriefNotification(`Rescue failed! ${arrested.join(' and ')} got arrested trying to break you out.`, 'danger');
    logAction(`The rescue goes sideways fast. Spotlights catch your crew mid-approach. ${arrested.join(' and ')} ${arrested.length > 1 ? 'are' : 'is'} hauled away in cuffs. Your sentence gets extended. Bad night for everyone.`);
    showJailScreen();
  }
}
window.attemptGangRescue = attemptGangRescue;

// Function to show gang management

// Gang management functions
function collectTribute() {
  if (!player.gang.gangMembers || player.gang.gangMembers.length === 0) {
    showBriefNotification('You need gang members to collect tribute!', 'danger');
    return;
  }

  // Check cooldown (5 minutes = 300 seconds)
  const tributeCooldown = 300;
  const currentTime = Date.now();
  const timeSinceLastTribute = Math.floor((currentTime - player.gang.lastTributeTime) / 1000);

  if (timeSinceLastTribute < tributeCooldown) {
    const timeRemaining = tributeCooldown - timeSinceLastTribute;
    const minutes = Math.floor(timeRemaining / 60);
    const seconds = timeRemaining % 60;
    showBriefNotification(`You must wait ${minutes}:${seconds.toString().padStart(2, '0')} before collecting tribute again.`, 'warning');
    return;
  }

  // Calculate tribute based on individual gang member experience levels
  const baseTributePerMember = 150;
  let cleanTribute = 0;
  let dirtyTribute = 0;

  // Calculate tribute from each gang member individually
  if (player.gang.gangMembers.length > 0) {
    player.gang.gangMembers.forEach(member => {
      const memberTribute = Math.floor(baseTributePerMember * member.tributeMultiplier);
      if (memberPaysCleanCash(member)) {
        cleanTribute += memberTribute;
      } else {
        dirtyTribute += memberTribute;
      }
    });
  } else {
    // Fallback for old save files without individual gang members
    dirtyTribute = player.gang.members * 180;
  }

  // Bonus based on turf controlled (dirty cash)
  const turfBonus = player.territory * 35;
  dirtyTribute += turfBonus;

  const totalTribute = cleanTribute + dirtyTribute;

  // Add clean cash to wallet, dirty cash to dirty money
  if (cleanTribute > 0) player.money += cleanTribute;
  if (dirtyTribute > 0) player.dirtyMoney = (player.dirtyMoney || 0) + dirtyTribute;
  player.gang.lastTributeTime = currentTime;

  // Track statistics
  updateStatistic('tributeCollected');
  updateStatistic('totalMoneyEarned', totalTribute);

  let bonusText = '';
  if (turfBonus > 0) {
    bonusText += ` (+$${turfBonus} turf bonus)`;
  }

  const breakdownParts = [];
  if (cleanTribute > 0) breakdownParts.push(`$${cleanTribute.toLocaleString()} clean`);
  if (dirtyTribute > 0) breakdownParts.push(`$${dirtyTribute.toLocaleString()} dirty`);
  const breakdownText = breakdownParts.join(', ');

  showBriefNotification(`Collected $${totalTribute.toLocaleString()} in tribute (${breakdownText})!${bonusText}`, 'success');
  logAction(`Your crew comes through! Envelopes stuffed with cash find their way to you. The family business is paying dividends (+${breakdownText}${bonusText}).`);
  updateUI();
  showGang(_currentGangTab); // Refresh the gang screen to show new cooldown
}

// Function to fire a gang member
async function fireGangMember(memberIndex) {
  if (memberIndex < 0 || memberIndex >= player.gang.gangMembers.length) {
    showBriefNotification('Invalid gang member selection.', 'warning');
    return;
  }

  const member = player.gang.gangMembers[memberIndex];

  // Confirm firing
  if (!await ui.confirm(`Are you sure you want to fire ${member.name}?<br><br>You will lose:<br>* ${member.power || 5} power<br>* Their tribute generation<br><br>This action cannot be undone.`)) {
    return;
  }

  // Remove the member from the gang first
  player.gang.gangMembers.splice(memberIndex, 1);
  player.gang.members = player.gang.gangMembers.length;

  // Recalculate power after removing member (handles turf power automatically)
  recalculatePower();

  // Update UI and refresh gang screen
  updateUI();
  showGang('roster');

  // Log the action with some flavor text
  const fireReasons = [
    'performance issues', 'disloyalty', 'unreliability', 'insubordination',
    'being a liability', 'not meeting expectations', 'poor judgment', 'security concerns'
  ];
  const reason = fireReasons[Math.floor(Math.random() * fireReasons.length)];

  logAction(`${member.name} has been terminated from your organization due to ${reason}. Word spreads quickly in the underworld - sometimes tough decisions must be made.`);

  // Achievement check in case this affects any achievements
  checkAchievements();
}

// Break an arrested gang member out of jail
async function breakoutGangMember(memberIndex) {
  if (memberIndex < 0 || memberIndex >= player.gang.gangMembers.length) {
    showBriefNotification('Invalid gang member selection.', 'warning');
    return;
  }

  const member = player.gang.gangMembers[memberIndex];
  if (!member.arrested) {
    showBriefNotification(`${member.name} is not in jail.`, 'warning');
    return;
  }

  // Cost and chance calculation
  const bribeCost = 5000 + (member.experienceLevel || 1) * 2000;
  const baseChance = 40;
  const infiltrationBonus = (player.skillTree.stealth?.infiltration || 0) * 3;
  const planningBonus = (player.skillTree.intelligence?.planning || 0) * 2;
  const successChance = Math.min(85, baseChance + infiltrationBonus + planningBonus);

  if (!await ui.confirm(
    `<strong>Jailbreak: ${member.name}</strong><br><br>` +
    'You\'ll need to grease some palms and pull some strings to get your crew member out.<br><br>' +
    `Bribe cost: <strong>$${bribeCost.toLocaleString()}</strong><br>` +
    `Success chance: <strong>${successChance}%</strong><br><br>` +
    'If the attempt fails, your heat will increase.<br><br>Proceed?'
  )) {
    return;
  }

  if (player.money < bribeCost) {
    showBriefNotification(`Not enough money! Need $${bribeCost.toLocaleString()}.`, 'danger');
    return;
  }

  player.money -= bribeCost;

  if (Math.random() * 100 < successChance) {
    // Success
    member.arrested = false;
    member.arrestTime = null;
    member.onOperation = false;
    showBriefNotification(`${member.name} has been broken out of jail!`, 'success');
    logAction(`The jailbreak worked! ${member.name} slips out through the back of the precinct, free and clear. Cost you $${bribeCost.toLocaleString()} in bribes, but loyalty like this isn't cheap.`);
  } else {
    // Failure
    player.heat += 8;
    showBriefNotification('Jailbreak failed! Heat increased.', 'danger');
    logAction(`The jailbreak attempt for ${member.name} went sideways. The guards were tipped off, and now the heat is on you. $${bribeCost.toLocaleString()} wasted and the cops are watching closer than ever (+8 heat).`);
  }

  updateUI();

  // Refresh whichever screen is currently visible
  if (document.getElementById('jailbreak-screen').style.display === 'block') {
    updateJailbreakPrisonerList();
  } else if (document.getElementById('jail-screen').style.display === 'block') {
    updatePrisonerList();
  } else {
    showGang('roster');
  }
}

// Function to show the jail screen
function showJailScreen() {
  hideAllScreens();
  document.getElementById('jail-screen').style.display = 'block';

  // Show player portrait behind bars
  displayPlayerJailPortrait();

  // Calculate escape odds for display
  let breakoutChance = player.breakoutChance + (player.skillTree.stealth.shadow_step * 3);
  if (hasPlayerPerk('iron_will')) breakoutChance += 10;
  // Synergy: Survivor (endurance + luck) bonus
  breakoutChance += Math.floor(getSynergyBonus('enduranceLuck') * 100);
  breakoutChance = Math.min(95, breakoutChance);

  const breakoutButton = document.getElementById('breakout-button');
  if (player.breakoutAttempts > 0) {
    breakoutButton.innerText = `Try to Break Out (${player.breakoutAttempts} left)`;
    breakoutButton.style.display = 'block';
  } else {
    breakoutButton.style.display = 'none';
  }

  // Escape odds display
  let oddsEl = document.getElementById('escape-odds-display');
  if (!oddsEl) {
    oddsEl = document.createElement('div');
    oddsEl.id = 'escape-odds-display';
    const breakoutBtn = document.getElementById('breakout-button');
    if (breakoutBtn && breakoutBtn.parentNode) {
      breakoutBtn.parentNode.insertBefore(oddsEl, breakoutBtn.nextSibling);
    }
  }
  if (player.breakoutAttempts > 0) {
    const chanceColor = breakoutChance >= 60 ? '#8a9a6a' : breakoutChance >= 40 ? '#c0a062' : '#8b3a3a';
    oddsEl.innerHTML = `<div style="text-align:center;margin:8px 0;padding:8px;background:rgba(20,18,10,0.6);border-radius:6px;border:1px solid ${chanceColor};">
      <strong style="color:${chanceColor};">Escape Odds: ${breakoutChance}%</strong>
      <div style="background:#1a1610;border-radius:4px;height:10px;margin:5px auto;max-width:200px;overflow:hidden;border:1px solid #3a3520;">
        <div style="height:100%;width:${breakoutChance}%;background:${chanceColor};transition:width 0.3s;"></div>
      </div>
      <small style="color:#8a7a5a;">Base ${player.breakoutChance}% + Stealth ${player.skillTree.stealth.shadow_step * 3}%${hasPlayerPerk('iron_will') ? ' + Iron Will 10%' : ''}${getSynergyBonus('enduranceLuck') > 0 ? ' + Survivor ' + Math.floor(getSynergyBonus('enduranceLuck') * 100) + '%' : ''}</small>
    </div>`;
    oddsEl.style.display = 'block';
  } else {
    oddsEl.style.display = 'none';
  }

  // Bribe guard button - costs scale with level and heat
  const bribeButton = document.getElementById('bribe-button');
  const bribeCostEl = document.getElementById('bribe-cost');
  if (bribeButton) {
    const bribeCost = Math.floor(1000 + (player.reputation || 0) * 15 + player.heat * 200);
    bribeButton.innerText = `Bribe Guard ($${bribeCost.toLocaleString()})`;
    bribeButton.style.display = player.money >= bribeCost ? 'inline-block' : 'inline-block';
    bribeButton.style.opacity = player.money >= bribeCost ? '1' : '0.5';
    if (bribeCostEl) {
      bribeCostEl.textContent = player.money >= bribeCost ? 'Grease some palms and walk free' : `Need $${bribeCost.toLocaleString()} (you have $${Math.floor(player.money).toLocaleString()})`;
    }
  }

  // Gang rescue button
  let rescueEl = document.getElementById('gang-rescue-section');
  if (!rescueEl) {
    rescueEl = document.createElement('div');
    rescueEl.id = 'gang-rescue-section';
    const bribeBtn = document.getElementById('bribe-button');
    if (bribeBtn && bribeBtn.parentNode) {
      bribeBtn.parentNode.insertBefore(rescueEl, bribeBtn.nextSibling);
    }
  }
  const availableMembers = (player.gang && player.gang.gangMembers) ? player.gang.gangMembers.filter(m => !m.arrested && !m.onOperation) : [];
  if (availableMembers.length > 0) {
    const rescueChance = Math.min(90, 20 + availableMembers.length * 10);
    rescueEl.innerHTML = `<div style="margin:12px 0;padding:12px;background:rgba(20,18,10,0.6);border-radius:8px;border:1px solid #c0a062;">
      <strong style="color:#c0a062;">Gang Rescue Operation</strong>
      <p style="color:#8a7a5a;font-size:0.9em;margin:4px 0;">Send your crew to break you out. More members = better odds, but anyone caught gets arrested too.</p>
      <div style="margin:6px 0;font-size:0.9em;">
        <span style="color:#f5e6c8;">Available crew: ${availableMembers.length}</span> |
        <span style="color:${rescueChance >= 60 ? '#8a9a6a' : '#c0a062'};">Success chance: ${rescueChance}%</span>
      </div>
      <button onclick="attemptGangRescue()" style="background:linear-gradient(135deg,#c0a062,#8b6d2a);color:#000;border:1px solid #c0a062;padding:8px 16px;border-radius:6px;cursor:pointer;font-weight:bold;margin-top:6px;">
        Call in the Crew
      </button>
    </div>`;
    rescueEl.style.display = 'block';
  } else {
    rescueEl.innerHTML = '';
    rescueEl.style.display = 'none';
  }

  // Request fresh jail roster from server
  if (typeof requestJailRoster === 'function') {
    requestJailRoster();
  }

  // Display prisoner list
  updatePrisonerList();

  // Reset and show TikTakToe game section
  resetTikTakToe();
  const tiktaktoeSection = document.getElementById('tiktaktoe-section');
  if (tiktaktoeSection) {
    tiktaktoeSection.style.display = 'block';
  }
}

// Function to display player's portrait behind bars in jail
function displayPlayerJailPortrait() {
  const portraitContainer = document.getElementById('player-jail-portrait');
  if (!portraitContainer) return;

  let portraitHTML = '';

  if (player.portrait && player.name) {
    portraitHTML = `
      <div style="position: relative; display: inline-block; margin: 20px auto;">
        <div style="background: linear-gradient(135deg, #1a1610, #14120a); padding: 20px; border-radius: 15px; border: 3px solid #6a5a3a; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);">
          <h3 style="color: #8b3a3a; margin: 0 0 15px 0; text-align: center;">Prisoner #${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}</h3>
          <div style="position: relative; display: inline-block;">
            <img src="${player.portrait}" alt="${player.name}"
               style="width: 120px; height: 120px; border-radius: 10px; object-fit: cover;
                  border: 3px solid #8a7a5a; filter: grayscale(20%) brightness(0.8);" />

            <!-- Prison bars overlay -->
            <div style="position: absolute; top: 0; left: 0; width: 100%; height: 100%;
                  background: repeating-linear-gradient(90deg,
                    transparent 0px, transparent 8px,
                    rgba(149, 165, 166, 0.8) 8px, rgba(149, 165, 166, 0.8) 12px);
                  border-radius: 10px; pointer-events: none;"></div>

            <!-- Additional dark overlay for prison effect -->
            <div style="position: absolute; top: 0; left: 0; width: 100%; height: 100%;
                  background: rgba(0, 0, 0, 0.3); border-radius: 10px; pointer-events: none;"></div>
          </div>
          <p style="color: #f5e6c8; margin: 15px 0 0 0; text-align: center; font-weight: bold; font-size: 1.1em;">${player.name}</p>
          <p style="color: #8a7a5a; margin: 5px 0 0 0; text-align: center; font-size: 0.9em; font-style: italic;">
            ${getReputationTier(player.reputation).name}
          </p>
        </div>
      </div>
    `;
  } else {
    portraitHTML = `
      <div style="text-align: center; padding: 20px; background: rgba(20, 18, 10, 0.6); border-radius: 10px; border: 2px solid #6a5a3a; margin: 20px;">
        <h3 style="color: #8b3a3a;">Behind Bars</h3>
        <p style="color: #f5e6c8;">You sit in your cell, contemplating your choices...</p>
      </div>
    `;
  }

  portraitContainer.innerHTML = portraitHTML;
}

// Function to update the prisoner list in jail
function updatePrisonerList() {
  const prisonerListContainer = document.getElementById('prisoner-list');
  if (!prisonerListContainer) return;

  let prisonerHTML = '';

  const roster = (typeof onlineWorldState !== 'undefined' && onlineWorldState.jailRoster) ? onlineWorldState.jailRoster : null;
  const onlinePlayers = roster ? roster.realPlayers : [];
  const bots = roster ? roster.bots : [];

  // === SECTION 0: Your Arrested Crew ===
  const arrestedCrew = (player.gang && player.gang.gangMembers) ? player.gang.gangMembers.filter(m => m.arrested) : [];
  if (arrestedCrew.length > 0) {
    prisonerHTML += `<div style="margin-bottom: 15px; padding: 10px; background: rgba(139, 58, 58, 0.15); border-radius: 8px; border: 1px solid #8b3a3a;">
      <h4 style="color: #8b3a3a; margin: 0 0 10px 0;">Your Crew Behind Bars</h4>
      <p style="color: #8a7a5a; margin-bottom: 8px; font-size: 0.85em;">Your people are locked up. ${player.inJail ? 'Get yourself out first before helping them.' : 'Grease some palms to get them out.'}</p>`;

    arrestedCrew.forEach(member => {
      const realIndex = player.gang.gangMembers.indexOf(member);
      const remaining = member.arrestTime ? Math.max(0, member.arrestTime - Date.now()) : 0;
      const timeLeft = remaining > 0 ? formatCountdown(remaining) : 'Releasing soon...';
      const expLevel = member.experienceLevel || 1;
      prisonerHTML += `
        <div style="background: rgba(139, 0, 0, 0.2); padding: 12px; margin: 8px 0; border-radius: 6px; border-left: 4px solid #8b3a3a;">
          <strong style="color: #f5e6c8;">${member.name}</strong> (Lv. ${expLevel})
          <br><small style="color: #8b3a3a;">Time Left: ${timeLeft}</small>
          ${player.inJail ? '<br><span style="color: #8a7a5a; font-size: 0.85em;">Cannot help others while imprisoned yourself</span>' :
            `<br><button onclick="breakoutGangMember(${realIndex})" style="margin-top: 8px; background: #8b3a3a; color: white; border:1px solid #c0a062; padding: 6px 14px; border-radius: 6px; cursor: pointer;">Break Out</button>`}
        </div>
      `;
    });

    prisonerHTML += '</div>';
  }

  // === SECTION 1: Online Players in Jail ===
  prisonerHTML += `<div style="margin-bottom: 15px; padding: 10px; background: rgba(192, 160, 98, 0.15); border-radius: 8px; border: 1px solid #c0a062;">
    <h4 style="color: #c0a062; margin: 0 0 10px 0;">Online Players in Jail</h4>`;

  if (onlinePlayers.length > 0) {
    onlinePlayers.forEach(p => {
      const isMe = (typeof onlineWorldState !== 'undefined') && p.playerId === onlineWorldState.playerId;
      prisonerHTML += `
        <div style="background: rgba(139, 0, 0, 0.2); padding: 12px; margin: 8px 0; border-radius: 6px; border-left: 4px solid #8b0000;">
          <strong style="color: #8b0000;">${p.name}</strong> - Time Left: ${Math.max(0, Math.ceil(p.jailTime))}s
          <br><small style="color: #8b3a3a;">Online Player * Level ${p.level || 1}</small>
          ${isMe ? '<br><span style="color: #8a7a5a; font-style: italic;">That\'s you!</span>' :
            (player.inJail ? '<br><span style="color: #8a7a5a; font-size: 0.85em;">Cannot help others while imprisoned yourself</span>' :
            `<br><button onclick="attemptPlayerJailbreak('${p.playerId}', '${p.name}')" style="margin-top: 8px; background: #c0a040; color: white; border:1px solid #c0a062; padding: 6px 14px; border-radius: 6px; cursor: pointer;">Break Out</button>`)}
        </div>
      `;
    });
  } else {
    prisonerHTML += '<p style="color: #8a7a5a; font-style: italic;">No online players currently in jail.</p>';
  }

  prisonerHTML += '</div>';

  // === SECTION 2: Rival Family Members (Server Bots) ===
  prisonerHTML += `<div style="margin-bottom: 15px; padding: 10px; background: rgba(139, 0, 0, 0.15); border-radius: 8px; border: 1px solid #8b0000;">
    <h4 style="color: #8b3a3a; margin: 0 0 5px 0;">Rival Family Members</h4>
    <p style="color: #8a7a5a; margin-bottom: 10px; font-size: 0.85em;">Break out rival family members to earn their respect.</p>`;

  if (bots.length > 0) {
    bots.forEach(bot => {
      const difficultyColor = ['#8a9a6a', '#c0a040', '#8b3a3a'][bot.difficulty - 1] || '#c0a040';
      const difficultyText = bot.securityLevel || ['Easy', 'Medium', 'Hard'][bot.difficulty - 1] || 'Unknown';
      prisonerHTML += `
        <div style="background: rgba(20, 18, 10, 0.4); padding: 12px; margin: 8px 0; border-radius: 6px; border-left: 4px solid ${difficultyColor};">
          <strong style="color: #f5e6c8;">${bot.name}</strong> - Sentence: ${bot.sentence}s
          <br><small style="color: ${difficultyColor};">Difficulty: ${difficultyText}</small>
          ${player.inJail ? '<br><span style="color: #8a7a5a; font-size: 0.85em;">Cannot help others while imprisoned yourself</span>' :
            `<br><button onclick="attemptBotJailbreak('${bot.botId}', '${bot.name.replace(/'/g, "\\'").replace(/"/g, '&quot;')}')" style="margin-top: 8px; background: #c0a062; color: white; border:1px solid #c0a062; padding: 6px 14px; border-radius: 6px; cursor: pointer;">Break Out (${bot.breakoutSuccess}%)</button>`}
        </div>
      `;
    });
  } else {
    prisonerHTML += '<p style="color: #8a7a5a; font-style: italic;">No rival family members currently locked up.</p>';
  }

  prisonerHTML += '</div>';

  prisonerListContainer.innerHTML = prisonerHTML;
}

// Function to attempt breaking out another prisoner
function breakoutPrisoner(prisonerIndex) {
  // Prevent breaking out others while player is in jail
  if (player.inJail) {
    showBriefNotification("You can't help other prisoners while you're locked up yourself!", 'danger');
    return;
  }

  const prisoner = jailPrisoners[prisonerIndex];
  if (!prisoner || prisoner.isPlayer) return;

  const successChance = prisoner.breakoutSuccess + (player.skillTree.stealth.shadow_step * 2);
  const success = Math.random() * 100 < successChance;

  if (success) {
  const repReward = Math.max(0.5, Math.round((prisoner.difficulty * 3 + 2) * 0.1 * 10) / 10);
  gainExperience(repReward);

    showBriefNotification(`${getRandomNarration('prisonerBreakoutSuccess')} You helped ${prisoner.name} escape! Gained ${repReward} respect.`, 'success');
    logAction(` You slip ${prisoner.name} the keys and watch them disappear into the night. Honor among thieves - your reputation on the streets grows (+${repReward} respect).`);

    // Remove prisoner from list
    jailPrisoners.splice(prisonerIndex, 1);
    updatePrisonerList();
    updateUI();

  } else {
    // Failed breakout - chance of getting caught
    const caughtChance = 40 - (player.skillTree.stealth.shadow_step * 3);
    if (Math.random() * 100 < caughtChance) {
      showBriefNotification(`${getRandomNarration('prisonerBreakoutFailure')} You've been caught and sent to jail!`, 'danger');
      logAction(`Busted! The guards catch you red-handed helping ${prisoner.name}. They're dragging you to a cell of your own.`);

      // Send player to jail properly
      sendToJail(2, { crimeName: 'Aiding a Prison Escape', riskLevel: 'high' }); // Lose 2 heat and go to jail

      // Add additional jail time for the failed breakout attempt (minimum 20 seconds)
      player.jailTime += Math.max(20, 15);

      // Ensure jail screen is shown after sendToJail
      setTimeout(() => {
        showJailScreen();
      }, 100); // Small delay to ensure proper screen switching

      return; // Exit early since player is now in jail
    } else {
      showBriefNotification(`${getRandomNarration('prisonerBreakoutFailure')} But you weren't caught.`, 'danger');
      logAction(`" The plan falls apart. ${prisoner.name} stays locked up, but at least you kept your head down. Sometimes discretion is the better part of valor.`);
    }
    updateUI();
  }
}

