// Function to start the game (always creates a NEW profile)
// Requires cloud login before proceeding.
async function startGame() {
  const auth = getAuthState();
  if (!auth.isLoggedIn) {
    // Force the player to create an account or sign in first
    showAuthModal({
      required: true,
      startOnRegister: true,
      onAuth: async () => {
        // After sign-in, check if they already have a save
        await _startGameAfterAuth();
      }
    });
    return;
  }
  // Already logged in -- check for existing save
  await _startGameAfterAuth();
}

async function _startGameAfterAuth() {
  // Check for a pre-loaded save or fetch one
  let hasSave = false;
  let save = window._pendingCloudSave || null;
  window._pendingCloudSave = null; // Always clear the cache regardless

  if (!save) {
    try { save = await cloudLoad(); } catch { save = null; }
  }
  if (save && save.data && validateSaveData(save.data)) {
    hasSave = true;
  } else {
    save = null;
  }

  if (hasSave) {
    // Player has an existing game -- ask what they want
    const choice = await new Promise(resolve => {
      const overlay = document.createElement('div');
      overlay.id = 'resume-or-new-overlay';
      overlay.style.cssText = `
        position:fixed;top:0;left:0;width:100%;height:100%;
        background:rgba(0,0,0,0.95);display:flex;align-items:center;
        justify-content:center;z-index:1000;padding:20px;box-sizing:border-box;
      `;
      overlay.innerHTML = `
        <div style="max-width:460px;width:100%;background:linear-gradient(135deg,rgba(20,18,10,0.98),rgba(30,20,10,0.98));
              padding:40px;border-radius:20px;border:2px solid #c0a062;box-shadow:0 20px 50px rgba(0,0,0,0.8);text-align:center;color:white;">
          <h2 style="color:#c0a062;font-size:1.8em;margin:0 0 12px 0;">Existing Game Found</h2>
          <p style="color:#d4c4a0;margin-bottom:8px;">
            <strong>${save.playerName || 'Unknown'}</strong> &mdash; Level ${save.data?.level || save.data?.player?.level || '?'}
          </p>
          <p style="color:#8a7a5a;font-size:0.9em;margin-bottom:28px;">What would you like to do?</p>
          <button id="resume-choice-btn" style="display:block;width:100%;padding:16px;margin-bottom:12px;
            background:linear-gradient(to bottom,#1a3a1a,#0a1a0a);border:2px solid #8a9a6a;border-radius:10px;
            color:#8a9a6a;font-size:1.1em;cursor:pointer;font-weight:bold;">Resume Game
            <span style="display:block;font-size:0.75em;color:#6a7a5a;font-weight:normal;margin-top:4px;">Pick up where you left off</span>
          </button>
          <button id="newgame-choice-btn" style="display:block;width:100%;padding:16px;margin-bottom:20px;
            background:linear-gradient(to bottom,#3a1a1a,#1a0808);border:2px solid #8b3a3a;border-radius:10px;
            color:#bb5555;font-size:1.1em;cursor:pointer;font-weight:bold;">Start Fresh
            <span style="display:block;font-size:0.75em;color:#885555;font-weight:normal;margin-top:4px;">Wipe your save and create a new character</span>
          </button>
          <button id="cancel-choice-btn" style="background:transparent;border:1px solid #6a5a3a;color:#8a7a5a;
            padding:10px 28px;border-radius:8px;cursor:pointer;font-size:0.95em;">Cancel</button>
        </div>
      `;
      document.body.appendChild(overlay);
      document.getElementById('resume-choice-btn').onclick = () => { overlay.remove(); resolve('resume'); };
      document.getElementById('newgame-choice-btn').onclick = () => { overlay.remove(); resolve('new'); };
      document.getElementById('cancel-choice-btn').onclick = () => { overlay.remove(); resolve('cancel'); };
    });

    if (choice === 'resume') {
      window.applyCloudSave(save);
      showBriefNotification(`Welcome back, ${save.playerName || player.name}!`, 'success');
      return;
    } else if (choice === 'new') {
      // Wipe the cloud save then start fresh
      try { await cloudDeleteSave(); } catch { /* ignore */ }
      resetPlayerForNewGame();
      showSimpleCharacterCreation();
      return;
    } else {
      // Cancelled -- stay on title screen
      return;
    }
  }

  // No existing save -- go straight to character creation
  resetPlayerForNewGame();
  showSimpleCharacterCreation();
}

// Simplified character creation system
async function showSimpleCharacterCreation() {
  // Hide main menu and intro screen during character creation
  document.getElementById('menu').style.display = 'none';
  document.getElementById('intro-screen').style.display = 'none';

  // Ensure player is in a clean state for character creation
  if (player.name && player.name.trim() !== '') {
    resetPlayerForNewGame();
  }

  // Use the auth username as the player name (already validated & unique at registration)
  const auth = getAuthState();
  player.name = auth.username;

  // Initialize playtime tracking
  if (!player.startTime) {
    player.startTime = Date.now();
  }

  // Now show portrait selection screen
  showPortraitSelection();
}

// Character creation helper variable
let selectedPortraitFile = '';

// Function to select portrait during character creation
function selectPortraitForCreation(portraitFile) {
  selectedPortraitFile = portraitFile;

  // Update button states
  document.querySelectorAll('.portrait-option').forEach(btn => {
    btn.classList.remove('selected');
  });
  const selectedBtn = document.querySelector(`[data-portrait="${portraitFile}"]`);
  if (selectedBtn) {
    selectedBtn.classList.add('selected');
  }

  // Update preview
  updateCharacterPreview();
}

// Function to update character preview
function updateCharacterPreview() {
  const previewName = document.getElementById('preview-name');
  const selectedPortrait = document.getElementById('selected-portrait');
  const createBtn = document.getElementById('create-character-btn');

  if (previewName) {
    previewName.textContent = player.name ? `Name: ${player.name}` : 'Name: Unknown';
  }

  // Show portrait if selected
  if (selectedPortraitFile && selectedPortrait) {
    selectedPortrait.src = selectedPortraitFile;
    selectedPortrait.style.display = 'block';
  }

  // Enable create button if portrait selected
  if (createBtn) {
    createBtn.disabled = !selectedPortraitFile;
  }
}

// Function to load portrait grid in character creation -- organized by gender
function loadPortraitGrid() {
  const portraitGrid = document.getElementById('portrait-grid');
  if (!portraitGrid) return;

  const malePortraits = [
    'profile_pics/White male.png',
    'profile_pics/Black male.png',
    'profile_pics/Asian male.png',
    'profile_pics/Mexican male.png',
    'profile_pics/Old Male.png',
    'profile_pics/Stylized White Male.png',
    'profile_pics/Stylized Black Male.png',
    'profile_pics/Stylized Asian Male.png',
    'profile_pics/Stylized Hispanic Male.png'
  ];

  const femalePortraits = [
    'profile_pics/White female.png',
    'profile_pics/Black female.png',
    'profile_pics/Asian female.png',
    'profile_pics/Mexican female.png',
    'profile_pics/Old Female.png',
    'profile_pics/Stylized White Female.png',
    'profile_pics/Stylized Black Female.png',
    'profile_pics/Stylized Asian Female.png',
    'profile_pics/Stylized Hispanic Female.png'
  ];

  const renderGroup = (portraits) => portraits.map(portrait => `
    <button class="portrait-option" data-portrait="${portrait}" onclick="selectPortraitForCreation('${portrait}')">
      <img src="${portrait}" alt="Portrait" />
    </button>
  `).join('');

  portraitGrid.innerHTML = `
    <div class="portrait-gender-section">
      <h3 style="grid-column: 1 / -1; color: #c0a062; font-size: 1.3em; margin: 10px 0 5px; border-bottom: 2px solid #c0a062; padding-bottom: 8px;">\uD83D\uDC68 Male</h3>
      ${renderGroup(malePortraits)}
    </div>
    <div class="portrait-gender-section">
      <h3 style="grid-column: 1 / -1; color: #e84393; font-size: 1.3em; margin: 20px 0 5px; border-bottom: 2px solid #e84393; padding-bottom: 8px;">\uD83D\uDC69 Female</h3>
      ${renderGroup(femalePortraits)}
    </div>
  `;
}

