function calculatePlaytime() {
  if (!player.startTime) {
    player.startTime = Date.now();
    return 0;
  }
  return Date.now() - player.startTime;
}

function formatPlaytime(milliseconds) {
  const hours = Math.floor(milliseconds / (1000 * 60 * 60));
  const minutes = Math.floor((milliseconds % (1000 * 60 * 60)) / (1000 * 60));
  return `${hours}h ${minutes}m`;
}

function formatTimestamp(timestamp) {
  const date = new Date(timestamp);
  return date.toLocaleDateString() + ' ' + date.toLocaleTimeString();
}

// Check if player is in a crew before a multiplayer-friendly action.
// Returns 'solo' if the player chooses to go solo, 'crew' if they navigate to crew screen, or 'cancel' to abort.
// If the player is already in a crew, returns 'proceed' immediately.
async function checkCrewBeforeAction(actionName, canSolo = true) {
  if (player.crewId) return 'proceed';
  const modal = new ModalSystem();
  const buttons = [];
  if (canSolo) {
    buttons.push({ text: 'Go Solo', class: 'modal-btn-secondary', value: 'solo', callback: () => true });
  }
  buttons.push({ text: 'Find a Crew', class: 'modal-btn-primary', value: 'crew', callback: () => true });
  buttons.push({ text: 'Cancel', class: 'modal-btn-secondary', value: 'cancel', callback: () => true });
  const choice = await modal.show(
    'No Crew',
    `<p style="color:#d4c4a0;">You're about to attempt <strong>${actionName}</strong> without a crew.</p>
     <p style="color:#8a7a5a;">Crew members boost your earnings by <strong>+15% each</strong> and every online member gets a 25% cut of your take.${canSolo ? ' You can still attempt this solo if you prefer.' : ' This action requires a crew.'}</p>`,
    buttons
  );
  if (choice === 'crew') {
    if (typeof showOnlineWorld === 'function') showOnlineWorld('crew');
    return 'crew';
  }
  return choice || 'cancel';
}
window.checkCrewBeforeAction = checkCrewBeforeAction;

function showBriefNotification(message, durationOrType = 2000) {
  // Support type strings as second arg: 'success', 'warning', 'danger', or a number for duration
  let duration = 3500;
  let borderColor = '#c0a062';
  let bgColor = 'rgba(20, 18, 10, 0.95)';

  if (typeof durationOrType === 'string') {
    duration = 5000;
    switch (durationOrType) {
      case 'success': borderColor = '#8a9a6a'; bgColor = 'rgba(20, 18, 10, 0.95)'; break;
      case 'warning': borderColor = '#c0a040'; bgColor = 'rgba(20, 18, 10, 0.95)'; break;
      case 'danger': borderColor = '#8b3a3a'; bgColor = 'rgba(20, 18, 10, 0.95)'; break;
    }
  } else if (typeof durationOrType === 'number') {
    duration = durationOrType;
  }

  // Stack notifications so they don't overlap
  const existing = document.querySelectorAll('.kd-notification');
  const topOffset = 20 + existing.length * 65;

  // Create notification element
  const notification = document.createElement('div');
  notification.className = 'kd-notification';
  notification.style.cssText = `
    position: fixed;
    top: ${topOffset}px;
    right: 20px;
    background: ${bgColor};
    color: white;
    padding: 15px 20px;
    border-radius: 8px;
    border: 2px solid ${borderColor};
    z-index: 10000;
    font-weight: bold;
    max-width: 400px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    animation: slideInRight 0.3s ease;
    cursor: pointer;
  `;
  notification.textContent = message;

  // Add animation keyframes
  if (!document.getElementById('notification-styles')) {
    const style = document.createElement('style');
    style.id = 'notification-styles';
    style.textContent = `
      @keyframes slideInRight {
        from { transform: translateX(100%); opacity: 0; }
        to { transform: translateX(0); opacity: 1; }
      }
      @keyframes slideOutRight {
        from { transform: translateX(0); opacity: 1; }
        to { transform: translateX(100%); opacity: 0; }
      }
    `;
    document.head.appendChild(style);
  }

  document.body.appendChild(notification);

  // Dismiss helper -- slides out and removes the element
  let dismissed = false;
  function dismiss() {
    if (dismissed) return;
    dismissed = true;
    clearTimeout(autoTimer);
    notification.style.animation = 'slideOutRight 0.3s ease';
    setTimeout(() => {
      if (notification.parentNode) {
        notification.parentNode.removeChild(notification);
      }
    }, 300);
  }

  // Click to dismiss
  notification.addEventListener('click', dismiss);

  // Auto-dismiss after duration
  const autoTimer = setTimeout(dismiss, duration);
}

