// Start the game when the page is fully loaded
if (document.readyState === 'complete') {
  startLoadingSequence();
} else {
  window.addEventListener('load', startLoadingSequence);
}

// Loading sequence with progress updates
function startLoadingSequence() {
  const loadingText = document.getElementById('loading-text');
  const loadingProgress = document.getElementById('loading-progress');
  const loadingPercentage = document.getElementById('loading-percentage');

  let progress = 0;
  const loadingSteps = [
    { text: 'Initializing the underworld...', duration: 300 },
    { text: 'Detecting screen dimensions...', duration: 500 },
    { text: 'Loading crime families...', duration: 400 },
    { text: 'Setting up territories...', duration: 300 },
    { text: 'Calibrating weapons...', duration: 400 },
    { text: 'Establishing connections...', duration: 600 },
    { text: 'Finalizing preparations...', duration: 300 }
  ];

  let currentStep = 0;
  let stepsComplete = false;
  let serverReady = false;
  let loadingFinished = false; // guard against duplicate completeLoading calls

  // -- Server health ping ---
  // Resolve the HTTP health URL from the same logic multiplayer.js uses.
  const SERVER_HEALTH_URL = (function () {
    try {
      if (window.__MULTIPLAYER_SERVER_URL__) {
        return window.__MULTIPLAYER_SERVER_URL__.replace(/^ws/, 'http').replace(/\/$/, '') + '/health';
      }
      const h = window.location.hostname;
      if (h === 'localhost' || h === '127.0.0.1') return 'http://localhost:3000/health';
    } catch (e) { /* fall through */ }
    return 'https://mafia-born.onrender.com/health';
  })();

  let pingAttempts = 0;
  let connectionTimedOut = false; // true once 50s elapses without server
  const MAX_PING_ATTEMPTS = 17; // ~51s of pinging (17 x 3s)

  function pingServer() {
    if (loadingFinished || connectionTimedOut) return;
    pingAttempts++;
    fetch(SERVER_HEALTH_URL, { cache: 'no-store', mode: 'no-cors' })
      .then(res => {
        if (res.type === 'opaque' || res.type === 'opaqueredirect') {
          return { __opaque: true };
        }
        if (res.ok) return res.json();
        throw new Error('Server returned ' + res.status);
      })
      .then(data => {
        if (connectionTimedOut) return; // Too late, already timed out
        if (data && data.__opaque) {
          sessionStorage.removeItem('mb_update_attempt');
          serverReady = true;
          window._offlineMode = false;
          if (stepsComplete) finishLoading();
          return;
        }
        // -- Version mismatch check ---
        // Only auto-update if the SERVER version is strictly newer than the
        // client version. This avoids reload loops when the client runs
        // ahead of the server (e.g. package.json not yet bumped).
        if (data.version && isNewerVersion(data.version, CURRENT_VERSION)) {
          const reloadKey = 'mb_update_attempt';
          const lastAttempt = sessionStorage.getItem(reloadKey);
          if (lastAttempt === data.version) {
            // Already reloaded once for this version -- don't loop
            console.warn(`[loading] Version mismatch persists after reload (local: ${CURRENT_VERSION}, server: ${data.version}). Proceeding anyway.`);
            sessionStorage.removeItem(reloadKey);
            serverReady = true;
            window._offlineMode = false;
            if (stepsComplete) finishLoading();
            return;
          }
          console.warn(`[loading] Newer version available! Local: ${CURRENT_VERSION} Server: ${data.version} -- auto-updating...`);
          loadingText.textContent = `Update found (v${CURRENT_VERSION} -> v${data.version}) -- refreshing...`;
          loadingProgress.style.width = '100%';
          loadingPercentage.textContent = '100%';
          sessionStorage.setItem(reloadKey, data.version);
          setTimeout(() => forceHardReload(), 1500);
          return;
        }

        // Version matches or client is ahead -- clear any stale reload marker
        sessionStorage.removeItem('mb_update_attempt');

        serverReady = true;
        window._offlineMode = false;
        if (stepsComplete) finishLoading();
      })
      .catch(_err => {
        if (loadingFinished || connectionTimedOut || pingAttempts >= MAX_PING_ATTEMPTS) {
          return;
        }
        if (stepsComplete) {
          loadingText.textContent = 'Waking up the server...';
          const serverNote = document.getElementById('loading-server-note');
          if (serverNote) serverNote.style.display = 'block';
        }
        setTimeout(pingServer, 3000);
      });
  }

  // Start pinging immediately so the server wakes while visual steps run
  pingServer();

  // -- Progressive timeout messages ---
  // 40s: warn the user it's taking longer than expected
  setTimeout(() => {
    if (!loadingFinished && !serverReady) {
      loadingText.textContent = 'Server is taking longer than expected...';
      const serverNote = document.getElementById('loading-server-note');
      if (serverNote) {
        serverNote.textContent = 'Please wait a moment longer.';
        serverNote.style.display = 'block';
      }
    }
  }, 40000);

  // 50s: give up and tell the user to refresh
  setTimeout(() => {
    if (!loadingFinished && !serverReady) {
      connectionTimedOut = true;
      console.warn('Loading timeout reached (50s). Server unreachable.');
      loadingText.textContent = 'Connection not established -- try refreshing the page';
      loadingProgress.style.width = '99%';
      loadingPercentage.textContent = '99%';
      const serverNote = document.getElementById('loading-server-note');
      if (serverNote) {
        serverNote.textContent = 'The server may be temporarily unavailable.';
        serverNote.style.display = 'block';
      }
    }
  }, 50000);

  function finishLoading() {
    if (loadingFinished) return; // prevent double-fire
    loadingFinished = true;
    completeLoading();
  }

  // -- Visual loading steps ---
  function updateLoading() {
    if (currentStep < loadingSteps.length) {
      const step = loadingSteps[currentStep];
      loadingText.textContent = step.text;
      progress = Math.min(99, Math.round(((currentStep + 1) / loadingSteps.length) * 100));
      loadingProgress.style.width = progress + '%';
      loadingPercentage.textContent = progress + '%';

      setTimeout(() => {
        currentStep++;
        updateLoading();
      }, step.duration);
    } else {
      // Visual steps done
      stepsComplete = true;
      if (serverReady) {
        finishLoading();
      } else {
        // Keep loading screen up while server wakes -- hold at 99%
        loadingText.textContent = 'Contacting the server...';
        loadingProgress.style.width = '99%';
        loadingPercentage.textContent = '99%';
        const serverNote = document.getElementById('loading-server-note');
        if (serverNote) serverNote.style.display = 'block';
        // finishLoading() will be called by pingServer once it succeeds
      }
    }
  }

  // Start loading sequence after brief delay
  setTimeout(updateLoading, 500);
}

function completeLoading() {
  const loadingText = document.getElementById('loading-text');
  const loadingProgress = document.getElementById('loading-progress');
  const loadingPercentage = document.getElementById('loading-percentage');

  // Final loading state
  loadingText.textContent = 'Welcome to the underworld!';
  loadingProgress.style.width = '100%';
  loadingPercentage.textContent = '100%';

  // Initialize game systems
  initGame();

  // Show offline retry buttons if server was unreachable
  if (window._offlineMode) {
    setTimeout(injectOfflineButtons, 100);
  }

  // Initialize mobile system if available
  if (typeof window.MobileSystem !== 'undefined') {
    window.MobileSystem.init();
  }

  // Hide loading screen and show game
  setTimeout(() => {
    const loadingScreen = document.getElementById('loading-screen');
    const gameDiv = document.getElementById('game');

    // Fade out loading screen
    loadingScreen.style.transition = 'opacity 1s ease-out, visibility 1s ease-out';
    loadingScreen.style.opacity = '0';
    loadingScreen.style.visibility = 'hidden';

    // Show game
    gameDiv.style.display = 'block';
    gameDiv.style.opacity = '0';
    gameDiv.style.transition = 'opacity 1s ease-in';

    // Fade in game after brief delay
    setTimeout(() => {
      gameDiv.style.opacity = '1';
    }, 100);

    // Remove loading screen from DOM after animation
    setTimeout(() => {
      if (loadingScreen.parentNode) {
        loadingScreen.parentNode.removeChild(loadingScreen);
      }
    }, 1500);
  }, 800);
}

// ==================== OFFLINE RETRY ====================
function retryServerConnection() {
  // Disable all retry buttons while attempting
  document.querySelectorAll('.offline-retry-btn').forEach(b => {
    b.disabled = true;
    b.textContent = 'Connecting...';
  });

  const healthUrl = (function () {
    try {
      if (window.__MULTIPLAYER_SERVER_URL__) {
        return window.__MULTIPLAYER_SERVER_URL__.replace(/^ws/, 'http').replace(/\/$/, '') + '/health';
      }
      const h = window.location.hostname;
      if (h === 'localhost' || h === '127.0.0.1') return 'http://localhost:3000/health';
    } catch (e) { /* fall through */ }
    return 'https://mafia-born.onrender.com/health';
  })();

  fetch(healthUrl, { cache: 'no-store' })
    .then(res => {
      if (res.ok) return res.json();
      throw new Error('Server returned ' + res.status);
    })
    .then(() => {
      window._offlineMode = false;
      showBriefNotification('Connected to server!', 'success');
      // Remove offline buttons
      document.querySelectorAll('.offline-retry-btn').forEach(b => b.remove());
      // Reconnect multiplayer if available
      if (typeof connectToOnlineWorld === 'function') {
        connectToOnlineWorld();
      }
    })
    .catch(() => {
      showBriefNotification('Server still unavailable. Try again later.', 'danger');
      document.querySelectorAll('.offline-retry-btn').forEach(b => {
        b.disabled = false;
        b.textContent = 'OFFLINE -- Tap to Retry';
      });
    });
}
window.retryServerConnection = retryServerConnection;

function injectOfflineButtons() {
  if (!window._offlineMode) return;
  const btnStyle = 'background:#8b3a3a;color:#f5e6c8;border:1px solid #c0a062;padding:4px 12px;border-radius:5px;cursor:pointer;font-size:0.8em;font-weight:bold;margin-left:10px;vertical-align:middle;';

  // Main menu header
  const menuHeader = document.querySelector('#menu .page-header h1');
  if (menuHeader && !document.getElementById('offline-retry-btn-menu')) {
    const btn = document.createElement('button');
    btn.id = 'offline-retry-btn-menu';
    btn.className = 'offline-retry-btn';
    btn.style.cssText = btnStyle;
    btn.textContent = 'OFFLINE -- Tap to Retry';
    btn.onclick = retryServerConnection;
    menuHeader.appendChild(btn);
  }

  // SafeHouse header
  const shHeader = document.querySelector('#safehouse .page-header h1');
  if (shHeader && !document.getElementById('offline-retry-btn-safehouse')) {
    const btn = document.createElement('button');
    btn.id = 'offline-retry-btn-safehouse';
    btn.className = 'offline-retry-btn';
    btn.style.cssText = btnStyle;
    btn.textContent = 'OFFLINE -- Tap to Retry';
    btn.onclick = retryServerConnection;
    shHeader.appendChild(btn);
  }
}
window.injectOfflineButtons = injectOfflineButtons;

// ==================== ECONOMY SINKS: DAILY UPKEEP ====================
// Deducts maintenance costs periodically (checked each updateUI cycle)
function processEconomySinks() {
  if (!player.lastUpkeepCollection) player.lastUpkeepCollection = Date.now();

  const now = Date.now();
  const hoursSinceLastUpkeep = (now - player.lastUpkeepCollection) / 3600000;

  // Check once per hour
  if (hoursSinceLastUpkeep < 1) return;

  let totalUpkeep = 0;
  const details = [];

  // Gang member wages ($50/member/hour)
  const gangSize = (player.gang && player.gang.gangMembers ? player.gang.gangMembers : []).length;
  if (gangSize > 0) {
    const gangWages = gangSize * 50 * Math.floor(hoursSinceLastUpkeep);
    totalUpkeep += gangWages;
    if (gangWages > 0) details.push(`Gang wages: $${gangWages.toLocaleString()}`);
  }

  // Business upkeep ($100-500/business/hour based on level)
  const businesses = player.businesses || [];
  businesses.forEach(b => {
    if (b.owned) {
      const bCost = (100 + (b.level || 1) * 50) * Math.floor(hoursSinceLastUpkeep);
      totalUpkeep += bCost;
      if (bCost > 0) details.push(`${b.name}: $${bCost.toLocaleString()}`);
    }
  });

  // Territory upkeep ($200/territory/hour)
  const territoryCount = (player.territories || []).length;
  if (territoryCount > 0) {
    const tCost = territoryCount * 200 * Math.floor(hoursSinceLastUpkeep);
    totalUpkeep += tCost;
    if (tCost > 0) details.push(`Territory defense: $${tCost.toLocaleString()}`);
  }

  // Vehicle maintenance ($25/vehicle/hour)
  const vehicles = (player.vehicles || []).filter(v => v.owned);
  if (vehicles.length > 0) {
    const vCost = vehicles.length * 25 * Math.floor(hoursSinceLastUpkeep);
    totalUpkeep += vCost;
    if (vCost > 0) details.push(`Vehicle upkeep: $${vCost.toLocaleString()}`);
  }

  if (totalUpkeep > 0) {
    // Cap at 10% of wealth to prevent total wipeout
    const cap = Math.floor(player.money * 0.1);
    const finalUpkeep = Math.min(totalUpkeep, cap);

    if (finalUpkeep > 0 && player.money > finalUpkeep) {
      player.money -= finalUpkeep;
      player.lastUpkeepCollection = now;
      logAction(`Hourly upkeep deducted: $${finalUpkeep.toLocaleString()} (${details.join(', ')})`, 'economy');
    } else {
      player.lastUpkeepCollection = now; // Still reset timer
    }
  } else {
    player.lastUpkeepCollection = now;
  }
}

// ==================== DAILY LOGIN REWARDS ====================
const DAILY_LOGIN_REWARDS = [
  { day: 1, money: 2000, rep: 2, label: '$2,000 + 2 Respect' },
  { day: 2, money: 3500, rep: 3, label: '$3,500 + 3 Respect' },
  { day: 3, money: 5000, rep: 4, buff: { type: 'cooldown_reduction', multiplier: 0.75, duration: 3600000, name: 'Quick Fingers' }, label: '$5K + 4 Respect + Quick Fingers (1h)' },
  { day: 4, money: 7500, rep: 5, label: '$7,500 + 5 Respect' },
  { day: 5, money: 10000, rep: 8, buff: { type: 'job_pay', multiplier: 1.25, duration: 3600000, name: 'Pay Day' }, label: '$10K + 8 Respect + Job Pay Boost (1h)' },
  { day: 6, money: 15000, rep: 10, label: '$15,000 + 10 Respect' },
  { day: 7, money: 25000, rep: 15, buff: { type: 'rep_boost', multiplier: 1.5, duration: 7200000, name: 'Respect Surge' }, label: '$25K + 15 Respect + 1.5x Respect (2h)' }
];

function checkDailyLogin() {
  if (!player.dailyLogin) player.dailyLogin = { lastClaimDate: null, streak: 0, totalDays: 0 };

  const today = new Date().toDateString();
  if (player.dailyLogin.lastClaimDate === today) return; // Already claimed

  // Show daily login popup
  const dayIndex = (player.dailyLogin.streak || 0) % 7;
  const reward = DAILY_LOGIN_REWARDS[dayIndex];

  let html = `<div style="text-align:center;padding:20px;">
    <h2 style="color:#d4af37;margin-bottom:16px;">Daily Login Reward</h2>
    <p style="color:#d4c4a0;margin-bottom:8px;">Day ${dayIndex + 1} of 7 -- Streak: ${player.dailyLogin.streak || 0} days</p>
    <div style="background:rgba(20,18,10,0.6);border:2px solid #d4af37;border-radius:12px;padding:20px;margin:16px auto;max-width:300px;">
      <p style="color:#d4af37;font-size:1.3em;font-weight:bold;">${reward.label}</p>
    </div>
    <div style="margin:16px 0;">`;

  // Show future rewards preview
  DAILY_LOGIN_REWARDS.forEach((r, i) => {
    const isCurrent = i === dayIndex;
    const isPast = i < dayIndex;
    html += `<div style="display:inline-block;width:40px;height:40px;line-height:40px;margin:4px;border-radius:50%;font-size:0.8em;font-weight:bold;${isCurrent ? 'background:#d4af37;color:#14120a;border:2px solid #fff;' : isPast ? 'background:#27ae60;color:#fff;' : 'background:#3a3520;color:#8a7a5a;'}">${i + 1}</div>`;
  });

  html += `</div>
    <button onclick="claimDailyLogin()" style="background:linear-gradient(135deg,#d4af37,#b8962e);color:#14120a;border:1px solid #c0a062;padding:14px 32px;border-radius:8px;cursor:pointer;font-weight:bold;font-size:1.1em;margin-top:12px;">Claim Reward</button>
  </div>`;

  // Use an overlay div
  const existing = document.getElementById('daily-login-overlay');
  if (existing) existing.remove();

  const overlay = document.createElement('div');
  overlay.id = 'daily-login-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;z-index:99999;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
  overlay.innerHTML = `<div style="background:linear-gradient(135deg,#14120a,#0d0b07);border:2px solid #c0a062;border-radius:16px;padding:30px;max-width:480px;width:90%;box-shadow:0 20px 60px rgba(0,0,0,0.8);">${html}</div>`;
  document.body.appendChild(overlay);
}

function claimDailyLogin() {
  if (!player.dailyLogin) player.dailyLogin = { lastClaimDate: null, streak: 0, totalDays: 0 };

  const today = new Date().toDateString();
  if (player.dailyLogin.lastClaimDate === today) {
    showBriefNotification('Already claimed today!', 'error');
    return;
  }

  // Check if streak is broken (more than 48h since last claim)
  const yesterday = new Date(Date.now() - 86400000).toDateString();
  if (player.dailyLogin.lastClaimDate && player.dailyLogin.lastClaimDate !== yesterday) {
    player.dailyLogin.streak = 0; // Reset streak
  }

  const dayIndex = player.dailyLogin.streak % 7;
  const reward = DAILY_LOGIN_REWARDS[dayIndex];

  player.money += reward.money;
  gainExperience(reward.rep);

  if (reward.buff) {
    if (!player.activeBuffs) player.activeBuffs = [];
    player.activeBuffs.push({
      ...reward.buff,
      expiresAt: Date.now() + reward.buff.duration
    });
    showBriefNotification(`Buff activated: ${reward.buff.name} (${Math.round(reward.buff.duration / 60000)}min)`, 'success');
  }

  player.dailyLogin.streak++;
  player.dailyLogin.totalDays++;
  player.dailyLogin.lastClaimDate = today;

  showBriefNotification(`Daily reward claimed: ${reward.label}`, 'success');
  logAction(`Daily login reward (Day ${dayIndex + 1}): ${reward.label}`, 'reward');

  // Notify server
  if (typeof sendMP === 'function') sendMP({ type: 'daily_login_claim' });

  // Close overlay
  const overlay = document.getElementById('daily-login-overlay');
  if (overlay) overlay.remove();

  updateUI();
}

// ==================== BUFF SYSTEM ====================
function getActiveBuff(type) {
  if (!player.activeBuffs) return null;
  // Clean expired buffs
  player.activeBuffs = player.activeBuffs.filter(b => b.expiresAt > Date.now());
  return player.activeBuffs.find(b => b.type === type) || null;
}

function getBuffMultiplier(type) {
  const buff = getActiveBuff(type);
  return buff ? buff.multiplier : 1;
}

function renderActiveBuffs() {
  if (!player.activeBuffs || player.activeBuffs.length === 0) return '';
  player.activeBuffs = player.activeBuffs.filter(b => b.expiresAt > Date.now());
  if (player.activeBuffs.length === 0) return '';

  let html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin:4px 0;">';
  player.activeBuffs.forEach(b => {
    const timeLeft = Math.max(0, Math.round((b.expiresAt - Date.now()) / 60000));
    html += `<span style="background:rgba(212,175,55,0.2);border:1px solid #d4af37;border-radius:4px;padding:2px 8px;font-size:0.8em;color:#d4af37;">${b.name} (${timeLeft}m)</span>`;
  });
  html += '</div>';
  return html;
}

// ==================== TITLE SYSTEM ====================
function equipTitle(achievementId) {
  const achievement = player.achievements.find(a => a.id === achievementId);
  if (achievement && achievement.unlocked && achievement.title) {
    player.title = achievement.title;
    showBriefNotification(`Title equipped: "${achievement.title}"`, 'success');
    updateUI();
  }
}

function getPlayerTitle() {
  return player.title || '';
}

// ==================== SKILL TREE RESPEC ====================
function respecSkillTree() {
  if (!player.respecCount) player.respecCount = 0;
  const cost = 10000 * Math.pow(2, player.respecCount); // Doubles each time

  if (player.money < cost) {
    showBriefNotification(`Not enough money! Reset costs $${cost.toLocaleString()}.`, 'error');
    return;
  }

  // Cancel any active training
  if (player.activeTraining) {
    player.activeTraining = null;
  }

  // Count total invested ranks
  let totalRanks = 0;
  if (player.skillTree) {
    for (const [treeName, nodes] of Object.entries(player.skillTree)) {
      for (const [nodeName, rank] of Object.entries(nodes)) {
        if (rank > 0) {
          totalRanks += rank;
          player.skillTree[treeName][nodeName] = 0;
        }
      }
    }
  }

  if (totalRanks === 0) {
    showBriefNotification('No skills to reset.', 'error');
    return;
  }

  player.money -= cost;
  player.respecCount++;

  showBriefNotification(`Skills reset! ${totalRanks} ranks cleared. Cost: $${cost.toLocaleString()}`, 'success');
  logAction(`All skills reset! ${totalRanks} ranks cleared for $${cost.toLocaleString()}. Train them again from scratch.`, 'skills');
  updateUI();
}

